DG.put("ath-pakhyaan-charitr-likhyate/81",{"n":81,"title":null,"title_roman":null,"page":1299,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1299,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":1299,"lines":[{"gurmukhi":"ਨਗਰ ਸਿਰੋਮਨਿ ਕੋ ਹੁਤੋ ਸਿੰਘ ਸਿਰੋਮਨਿ ਭੂਪ।","roman":"Nagar siromni ko huto singh siromni bhoop |","meaning_en":"In the city of Siromani there was a king, Siromani Singh;","page":1299,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਦਰਬੁ ਘਰ ਮੈ ਧਰੇ ਸੁੰਦਰ ਕਾਮ ਸਰੂਪ। ੧।","roman":"Amit darbu ghar mai dhare sundar kaam saroop | 1 |","meaning_en":"he kept boundless wealth in his house, and was handsome as the form of Kama.","page":1299,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[2],"number_text":"੨।","page":1301,"lines":[{"gurmukhi":"ਦ੍ਰਿਗ ਧੰਨ੍ਯਾ ਤਾ ਕੀ ਬਰ ਨਾਰੀ। ਨ੍ਰਿਪ ਕੋ ਰਹੈ ਲਾਜ ਤੇ ਪ੍ਯਾਰੀ।","roman":"Drig dhannyaa taa kee bar naaree | nrip ko rahai laaj te pyaaree |","meaning_en":"Drig Dhanya was his excellent wife; she was dearer to the king than his honour.","page":1301,"meaning_status":"draft","note":"ਲਾਜ ਤੇ ਪ੍ਯਾਰੀ: read as 'dearer than honour'; could be 'dear as honour'."},{"gurmukhi":"ਏਕ ਦਿਵਸ ਰਾਜ ਘਰ ਆਯੋ। ਰੰਗ ਨਾਥ ਜੋਗਿਯਹਿ ਬੁਲਾਯੋ। ੨।","roman":"Ek divas raaj ghar aayo | rang naath jogiyhi bulaayo | 2 |","meaning_en":"One day the king came home and sent for the yogi Rang Nath.","page":1301,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[3],"number_text":"੩।","page":1301,"lines":[{"gurmukhi":"ਬ੍ਰਹਮ ਬਾਦ ਤਾ ਸੌ ਕਿਯੋ ਰਾਜੈ ਨਿਕਟਿ ਬੁਲਾਇ।","roman":"Braham baad taa sau kiyo raajai nikti bulaai |","meaning_en":"The king called him near and held a discourse with him on Brahm;","page":1301,"meaning_status":"draft","note":"ਬ੍ਰਹਮ ਬਾਦ: discourse on the Supreme (Brahm)."},{"gurmukhi":"ਜੁ ਕਛੁ ਕਥਾ ਤਿਨ ਸੌ ਭਈ ਸੋ ਮੈ ਕਹਤ ਬਨਾਇ। ੩।","roman":"Ju kachhu kathaa tin sau bhaee so mai kahat banaai | 3 |","meaning_en":"whatever talk passed between them, I tell it properly.","page":1301,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":1301,"lines":[{"gurmukhi":"ਏਕ ਨਾਥ ਸਭ ਜਗਤ ਮੈ ਬ੍ਯਾਪਿ ਰਹਿਯੋ ਸਭ ਦੇਸ।","roman":"Ek naath sabh jagat mai byaapi rahiyo sabh des |","meaning_en":"\"The one Lord pervades the whole world, every land;","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਜੋਨਿਨ ਮੈ ਰਵਿ ਰਹਿਯੋ ਊਚ ਨੀਚ ਕੇ ਭੇਸ। ੪।","roman":"Sabh jonin mai ravi rahiyo ooch neech ke bhes | 4 |","meaning_en":"He is present in all species of life, in the guise of high and low.","page":1301,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[5],"number_text":"੫।","page":1301,"lines":[{"gurmukhi":"ਸਰਬ ਬ੍ਯਾਪੀ ਸ੍ਰੀ ਪਤਿ ਜਾਨਹੁ। ਸਭ ਹੀ ਕੋ ਪੋਖਕ ਕਰਿ ਮਾਨਹੁ।","roman":"Sarab byaapee sree pati jaanhu | sabh hee ko pokhak kari maanhu |","meaning_en":"Know the Lord of Lakshmi to be all-pervading; regard Him as the sustainer of all.","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਸਰਬ ਦਯਾਲ ਮੇਘ ਜਿਮਿ ਢਰਈ। ਸਭ ਕਾਹੂ ਕਰ ਕਿਰਪਾ ਕਰਈ। ੫।","roman":"Sarab dayaal megh jimi dharaee | sabh kaahoo kar kirpaa karaee | 5 |","meaning_en":"Kind to all, He pours down like a cloud; He shows grace to everyone.","page":1301,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[6],"number_text":"੬।","page":1301,"lines":[{"gurmukhi":"ਸਭ ਕਾਹੂ ਕੋ ਪੋਖਈ ਸਭ ਕਾਹੂ ਕੌ ਦੇਇ।","roman":"Sabh kaahoo ko pokhaee sabh kaahoo kau dei |","meaning_en":"He sustains everyone, He gives to everyone;","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਤਾ ਤੇ ਮੁਖ ਫੇਰਈ ਮਾਗਿ ਮੀਚ ਕਹ ਲੇਇ। ੬।","roman":"Jo taa te mukh pheraee maagi meech kah lei | 6 |","meaning_en":"whoever turns his face from Him asks for death and receives it.","page":1301,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":1301,"lines":[{"gurmukhi":"ਏਕਨ ਸੋਖੈ ਏਕਨ ਭਰੈ। ਏਕਨ ਮਾਰੈ ਇਕਨਿ ਉਬਰੈ।","roman":"Ekan sokhai ekan bharai | ekan maarai ikni ubrai |","meaning_en":"Some He dries up, some He fills; some He kills, some He saves;","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਏਕਨ ਘਟਵੈ ਏਕ ਬਢਾਵੈ। ਦੀਨ ਦਯਾਲ ਯੌ ਚਰਿਤ ਦਿਖਾਵੈ। ੭।","roman":"Ekan ghatvai ek badhaavai | deen dayaal yau charit dikhaavai | 7 |","meaning_en":"some He lessens, some He increases; so the Compassionate to the lowly shows His play.","page":1301,"meaning_status":"draft"}]},{"type":"verse","number":[8],"number_text":"੮।","page":1301,"lines":[{"gurmukhi":"ਰੂਪ ਰੇਖ ਜਾ ਕੇ ਕਛੁ ਨਾਹੀ। ਭੇਖ ਅਭੇਖ ਸਭ ਕੇ ਘਟ ਮਾਹੀ।","roman":"Roop rekh jaa ke kachhu naahee | bhekh abhekh sabh ke ghat maahee |","meaning_en":"He has no form or outline; with a guise and without a guise He is within every heart.","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਪਰ ਕ੍ਰਿਪਾ ਚਛੁ ਕਰਿ ਹੇਰੈ। ਤਾ ਕੀ ਕੌਨ ਛਾਹ ਕੌ ਛੇਰੈ। ੮।","roman":"Jaa par kripaa chachhu kari herai | taa kee kaun chhaah kau chherai | 8 |","meaning_en":"On whom He looks with the eye of grace, who can touch even his shadow?","page":1301,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":1301,"lines":[{"gurmukhi":"ਜਛ ਭੁਜੰਗ ਅਕਾਸ ਬਨਾਯੋ। ਦੇਵ ਅਦੇਵ ਥਪਿ ਬਾਦਿ ਰਚਾਯੋ।","roman":"Jachh bhujang akaas banaayo | dev adev thapi baadi rachaayo |","meaning_en":"He made the yakshas, serpents and the sky; He set up gods and demons and created strife between them.","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਭੂਮਿ ਬਾਰਿ ਪੰਚ ਤਤੁ ਪ੍ਰਕਾਸਾ। ਆਪਹਿ ਦੇਖਤ ਬੈਠ ਤਮਾਸਾ। ੯।","roman":"Bhoomi baari panch tatu prakaasaa | aaphi dekhat baith tamaasaa | 9 |","meaning_en":"He brought forth earth, water, the five elements, and sits watching the show Himself.","page":1301,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[10],"number_text":"੧੦।","page":1301,"lines":[{"gurmukhi":"ਜੀਵ ਜੰਤ ਸਭ ਥਾਪਿ ਕੈ ਪੰਥ ਬਨਾਏ ਦੋਇ।","roman":"Jeev jant sabh thaapi kai panth banaae doi |","meaning_en":"Having set up all living beings, He made two paths;","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਝਗਰਿ ਪਚਾਏ ਆਪਿ ਮਹਿ ਮੋਹਿ ਨ ਚੀਨੈ ਕੋਇ। ੧੦।","roman":"Jhagri pachaae aapi mahi mohi na cheenai koi | 10 |","meaning_en":"He made them quarrel and wear themselves out among themselves; no one recognises Me.","page":1301,"meaning_status":"draft","note":"ਮੋਹਿ ਨ ਚੀਨੈ ਕੋਇ: lit. 'no one recognises me', as if in the Lord's own voice; printed so."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1301,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":1301,"lines":[{"gurmukhi":"ਯਹ ਸਭ ਭੇਦ ਸਾਧੁ ਕੋਊ ਜਾਨੈ। ਸਤਿਨਾਮੁ ਕੋ ਤਤ ਪਛਾਨੈ।","roman":"Yah sabh bhed saadhu ko'oo jaanai | satinaamu ko tat pachhaanai |","meaning_en":"Some rare holy man knows this whole secret, and recognises the essence of the True Name;","page":1301,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਸਾਧਕ ਯਾ ਕੌ ਲਖਿ ਪਾਵੈ। ਜਨਨੀ ਜਠਰ ਬਹੁਰਿ ਨਹਿ ਆਵੈ। ੧੧।","roman":"Jo saadhak yaa kau lakhi paavai | jannee jathar bahuri nahi aavai | 11 |","meaning_en":"the seeker who perceives this does not come again into a mother's womb.\"","page":1301,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[12],"number_text":"੧੨।","page":1303,"lines":[{"gurmukhi":"ਜਬ ਜੋਗੀ ਐਸੇ ਕਹਿਯੋ ਤਬ ਰਾਜੈ ਮੁਸਕਾਇ।","roman":"Jab jogee aise kahiyo tab raajai muskaai |","meaning_en":"When the yogi had said this, the king smiled,","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਤਤ ਬ੍ਰਹਮ ਕੇ ਬਾਦਿ ਕੌ ਉਚਰਤ ਭਯੋ ਬਨਾਇ। ੧੨।","roman":"Tat braham ke baadi kau uchrat bhayo banaai | 12 |","meaning_en":"and spoke well on the discourse of the essence of Brahm:","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[13],"number_text":"੧੩।","page":1303,"lines":[{"gurmukhi":"ਜੋਗੀ ਡਿੰਭ ਕਿ ਜੋਗੀ ਜਿਯਰੋ। ਜੋਗੀ ਦੇਹ ਕਿ ਜੋਗੀ ਹਿਯਰੋ।","roman":"Jogee dinbh ki jogee jiyro | jogee deh ki jogee hiyro |","meaning_en":"\"Is the yogi a show, or is the yogi the soul? Is the yogi the body, or is the yogi the heart?","page":1303,"meaning_status":"draft","note":"ਡਿੰਭ: 'pretence, outward show'."},{"gurmukhi":"ਸੋ ਜੋਗੀ ਜੋ ਜੋਗ ਪਛਾਨੈ। ਸਤਿਨਾਮੁ ਬਿਨੁ ਅਵਰੁ ਨ ਜਾਨੈ। ੧੩।","roman":"So jogee jo jog pachhaanai | satinaamu binu avru na jaanai | 13 |","meaning_en":"He is a yogi who recognises yoga, and knows nothing but the True Name.","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[14],"number_text":"੧੪।","page":1303,"lines":[{"gurmukhi":"ਡਿੰਭ ਦਿਖਾਯੋ ਜਗਤ ਕੋ ਜੋਗੁ ਨ ਉਪਜਿਯੋ ਜੀਯ।","roman":"Dinbh dikhaayo jagat ko jogu na upjiyo jeey |","meaning_en":"Some showed a pretence to the world, but yoga never arose in their hearts;","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਜਗ ਕੇ ਸੁਖ ਤੇ ਗਯੋ ਜਨਮ ਬ੍ਰਿਥਾ ਗੇ ਕੀਯ। ੧੪।","roman":"Yaa jag ke sukh te gayo janam brithaa ge keey | 14 |","meaning_en":"they lost the joys of this world, and went, having made their birth vain.\"","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[15],"number_text":"੧੫।","page":1303,"lines":[{"gurmukhi":"ਤਬ ਜੋਗੀ ਹਸਿ ਬਚਨ ਉਚਾਰੋ। ਸੁਨਹੁ ਰਾਵ ਜੂ ਗ੍ਯਾਨ ਹਮਾਰੋ।","roman":"Tab jogee hasi bachan uchaaro | sunhu raav joo gyaan hamaaro |","meaning_en":"Then the yogi laughed and said, \"Listen, O king, to my knowledge:","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਜੋਗੀ ਜੋ ਜੋਗ ਪਛਾਨੈ। ਸਤਿਨਾਮੁ ਬਿਨੁ ਅਵਰੁ ਨ ਜਾਨੈ। ੧੫।","roman":"So jogee jo jog pachhaanai | satinaamu binu avru na jaanai | 15 |","meaning_en":"he is a yogi who recognises yoga, and knows nothing but the True Name.","page":1303,"meaning_status":"draft","note":"Printed in the same words as 81.22.1."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[16],"number_text":"੧੬।","page":1303,"lines":[{"gurmukhi":"ਜਬ ਚਾਹਤ ਹੈ ਆਤਮਾ ਇਕ ਤੇ ਭਯੋ ਅਨੇਕ।","roman":"Jab chaahat hai aatmaa ik te bhayo anek |","meaning_en":"When the Self wishes, from one it becomes many;","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਅਨਿਕ ਭਾਤਿ ਪਸਰਤ ਜਗਤ ਬਹੁਰਿ ਏਕ ਕੋ ਏਕ। ੧੬।","roman":"Anik bhaati pasrat jagat bahuri ek ko ek | 16 |","meaning_en":"it spreads out as the world in many ways, and then again becomes one, the One.","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[17],"number_text":"੧੭।","page":1303,"lines":[{"gurmukhi":"ਯਹ ਨਹਿ ਮਰੈ ਨ ਕਾਹੂ ਮਾਰੈ। ਭੂਲਾ ਲੋਕ ਭਰਮੁ ਬੀਚਾਰੈ।","roman":"Yah nahi marai na kaahoo maarai | bhoolaa lok bharmu beechaarai |","meaning_en":"It does not die, nor does it kill anyone; deluded people think in illusion.","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਘਟ ਘਟ ਬ੍ਯਾਪਕ ਅੰਤਰਜਾਮੀ। ਸਭ ਹੀ ਮਹਿ ਰਵਿ ਰਹਿਯੋ ਸੁਆਮੀ। ੧੭।","roman":"Ghat ghat byaapak antarjaamee | sabh hee mahi ravi rahiyo suaamee | 17 |","meaning_en":"The Knower of hearts pervades every heart; the Master is present in all.","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[18],"number_text":"੧੮।","page":1303,"lines":[{"gurmukhi":"ਘੋਰਾ ਕਹੂੰ ਭਯੋ ਕਹੂੰ ਹਾਥੀ ਹ੍ਵੈ ਕੈ ਗਯੋ ਕਹੂੰ","roman":"Ghoraa kahoon bhayo kahoon haathee hvai kai gayo kahoon","meaning_en":"Somewhere He became a horse, somewhere He went as an elephant, somewhere","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਪੰਛੀ ਰੂਪ ਲਯੋ ਕਹੂੰ ਫਲ ਫੂਲ ਰਹਿਯੋ ਹੈ।","roman":"Panchhee roop layo kahoon phal phool rahiyo hai |","meaning_en":"He took a bird's form, somewhere He abides as fruit and flower;","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਪਾਵਕ ਹ੍ਵੈ ਦਹਿਯੋ ਕਹੂੰ ਪੌਨ ਰੂਪ ਕਹਿਯੋ ਕਹੂੰ","roman":"Paavak hvai dahiyo kahoon paun roop kahiyo kahoon","meaning_en":"somewhere He burned as fire, somewhere He is spoken of as the form of wind,","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਚੀਤ ਹ੍ਵੈ ਕੈ ਗਹਿਯੋ ਕਹੂੰ ਪਾਨੀ ਹ੍ਵੈ ਕੈ ਬਹਿਯੋ ਹੈ।","roman":"Cheet hvai kai gahiyo kahoon paanee hvai kai bahiyo hai |","meaning_en":"somewhere He became a leopard and seized, somewhere He flowed as water;","page":1303,"meaning_status":"draft","note":"ਚੀਤ: read as 'cheetah, leopard'; could be 'mind'; uncertain."},{"gurmukhi":"ਅੰਬਰ ਉਤਾਰੇ ਰਾਵਨਾਦਿਕ ਸੰਘਾਰੇ ਕਹੂੰ","roman":"Anbar utaare raavnaadik sanghaare kahoon","meaning_en":"somewhere He took away garments, somewhere He destroyed Ravan and the rest,","page":1303,"meaning_status":"draft","note":"ਅੰਬਰ ਉਤਾਰੇ: 'took off garments' or 'brought down from the sky'; uncertain."},{"gurmukhi":"ਬਨ ਮੈ ਬਿਹਾਰੇ ਐਸੇ ਬੇਦਨ ਮੈ ਕਹਿਯੋ ਹੈ।","roman":"Ban mai bihaare aise bedan mai kahiyo hai |","meaning_en":"He roamed in the forest: so it is told in the Vedas;","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਪੁਰਖ ਹ੍ਵੈ ਆਪੁ ਕਹੂੰ ਇਸਤ੍ਰਿਨ ਕੋ ਰੂਪ ਧਰਿਯੋ","roman":"Purakh hvai aapu kahoon istrin ko roop dhariyo","meaning_en":"somewhere He Himself became a man, somewhere He took the form of women;","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਮੂਰਖਨ ਭੇਦ ਤਾ ਕੋ ਨੈਕਹੂੰ ਨ ਲਹਿਯੋ ਹੈ। ੧੮।","roman":"Moorkhan bhed taa ko naikhoon na lahiyo hai | 18 |","meaning_en":"the fools have not grasped His secret even a little.","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1303,"meaning_status":"draft"},{"type":"verse","number":[19],"number_text":"੧੯।","page":1303,"lines":[{"gurmukhi":"ਕਵਨ ਮਾਰੈ ਕਾ ਕੋ ਕੋਊ ਮਾਰੈ। ਭੂਲਾ ਲੋਕ ਭਰਮ ਬੀਚਾਰੈ।","roman":"Kavan maarai kaa ko ko'oo maarai | bhoolaa lok bharam beechaarai |","meaning_en":"Who kills, and whom does anyone kill? Deluded people think in illusion.","page":1303,"meaning_status":"draft"},{"gurmukhi":"ਯਹ ਨ ਮਰਤ ਮਾਰਤ ਹੈ ਨਾਹੀ। ਯੌ ਰਾਜਾ ਸਮਝਹੁ ਮਨ ਮਾਹੀ। ੧੯।","roman":"Yah na marat maarat hai naahee | yau raajaa samajhhu man maahee | 19 |","meaning_en":"This neither dies nor kills; understand this in your mind, O king.","page":1303,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[20],"number_text":"੨੦।","page":1305,"lines":[{"gurmukhi":"ਬਿਨਾ ਨਾਮ ਤਾ ਕੇ ਜਪੇ ਬਾਲ ਬ੍ਰਿਧ ਕੋਊ ਹੋਇ।","roman":"Binaa naam taa ke jape baal bridh ko'oo hoi |","meaning_en":"Without repeating His Name, whether one is young or old,","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਰਾਵ ਰੰਕ ਰਾਜਾ ਸਭੈ ਜਿਯਤ ਨ ਰਹਸੀ ਕੋਇ। ੨੦।","roman":"Raav rank raajaa sabhai jiyat na rahsee koi | 20 |","meaning_en":"noble, pauper or king, all of them: none will remain alive.","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[21],"number_text":"੨੧।","page":1305,"lines":[{"gurmukhi":"ਸਤਿਨਾਮੁ ਜੋ ਜਿਯ ਲਖਿ ਪਾਵੈ। ਤਾ ਕੇ ਕਾਲ ਨਿਕਟ ਨਹਿ ਆਵੈ।","roman":"Satinaamu jo jiy lakhi paavai | taa ke kaal nikat nahi aavai |","meaning_en":"Whoever perceives the True Name in his heart, death does not come near him;","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨਾ ਨਾਮ ਤਾ ਕੇ ਜੋ ਰਹਿ ਹੈ। ਬਨ ਗਿਰ ਪੁਰ ਮੰਦਰ ਸਭ ਢਹਿ ਹੈ। ੨੧।","roman":"Binaa naam taa ke jo rahi hai | ban gir pur mandar sabh dhahi hai | 21 |","meaning_en":"for those who live without His Name, forest, mountain, city and temple will all crumble.","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[22],"number_text":"੨੨।","page":1305,"lines":[{"gurmukhi":"ਚਕਿਯਾ ਕੈਸੇ ਪਟ ਬਨੇ ਗਗਨ ਭੂਮਿ ਪੁਨਿ ਦੋਇ।","roman":"Chakiyaa kaise pat bane gagan bhoomi puni doi |","meaning_en":"Like the two stones of a hand-mill are these two, sky and earth;","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਦੁਹੂੰ ਪੁਰਨ ਮੈ ਆਇ ਕੈ ਸਾਬਿਤ ਗਯਾ ਨ ਕੋਇ। ੨੨।","roman":"Duhoon puran mai aai kai saabit gayaa na koi | 22 |","meaning_en":"coming between the two, no one has gone out whole.","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[23],"number_text":"੨੩।","page":1305,"lines":[{"gurmukhi":"ਸਤਿਨਾਮ ਜੋ ਪੁਰਖ ਪਛਾਨੈ। ਸਤਿਨਾਮ ਲੈ ਬਚਨ ਪ੍ਰਮਾਨੈ।","roman":"Satinaam jo purakh pachhaanai | satinaam lai bachan pramaanai |","meaning_en":"The man who recognises the True Name, who takes the True Name and holds its word as proof,","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿਨਾਮੁ ਮਾਰਗ ਲੈ ਚਲਹੀ। ਤਾ ਕੋ ਕਾਲ ਨ ਕਬਹੂੰ ਦਲਹੀ। ੨੩।","roman":"Satinaamu maarag lai chalhee | taa ko kaal na kabhoon dalhee | 23 |","meaning_en":"who walks on the path of the True Name, death never crushes him.\"","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[24],"number_text":"੨੪।","page":1305,"lines":[{"gurmukhi":"ਐਸੇ ਬਚਨਨ ਸੁਨਤ ਹੀ ਰਾਜਾ ਭਯੋ ਉਦਾਸੁ।","roman":"Aise bachnan sunat hee raajaa bhayo udaasu |","meaning_en":"Hearing such words, the king became detached;","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਭੂਮਿ ਦਰਬੁ ਘਰ ਰਾਜ ਤੇ ਚਿਤ ਮੈ ਭਯੋ ਨਿਰਾਸੁ। ੨੪।","roman":"Bhoomi darbu ghar raaj te chit mai bhayo niraasu | 24 |","meaning_en":"in his mind he lost all desire for land, wealth, home and kingdom.","page":1305,"meaning_status":"draft"}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":1305,"lines":[{"gurmukhi":"ਜਬ ਰਾਨੀ ਐਸੇ ਸੁਨਿਯੋ ਦੁਖਤ ਭਈ ਮਨ ਮਾਹ।","roman":"Jab raanee aise suniyo dukhat bhaee man maah |","meaning_en":"When the queen heard of this, she grieved in her mind;","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਦੇਸ ਦਰਬੁ ਗ੍ਰਿਹ ਛਾਡਿ ਕੈ ਜਾਤ ਲਖਿਯੋ ਨਰ ਨਾਹ। ੨੫।","roman":"Des darbu grih chhaadi kai jaat lakhiyo nar naah | 25 |","meaning_en":"she saw the lord of men about to leave country, wealth and home.","page":1305,"meaning_status":"draft"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":1305,"lines":[{"gurmukhi":"ਤਬ ਰਾਨੀ ਅਤਿ ਦੁਖਿਤ ਹ੍ਵੈ ਮੰਤ੍ਰੀ ਲਯੋ ਬੁਲਾਇ।","roman":"Tab raanee ati dukhit hvai mantree layo bulaai |","meaning_en":"Then the queen, in great distress, called the minister:","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਕ੍ਯੋ ਹੂੰ ਨ੍ਰਿਪ ਗ੍ਰਿਹ ਰਾਖਿਯੈ ਕੀਜੈ ਕਛੂ ਉਪਾਇ। ੨੬।","roman":"Kyo hoon nrip grih raakhiyai keejai kachhoo upaai | 26 |","meaning_en":"\"Somehow keep the king at home; devise some means.\"","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[27],"number_text":"੨੭।","page":1305,"lines":[{"gurmukhi":"ਤਬ ਮੰਤ੍ਰੀ ਇਮਿ ਬਚਨ ਉਚਾਰੇ। ਸੁਨੁ ਰਾਨੀ ਤੈ ਮੰਤ੍ਰ ਹਮਾਰੇ।","roman":"Tab mantree imi bachan uchaare | sunu raanee tai mantr hamaare |","meaning_en":"Then the minister said, \"Listen, queen, to my counsel:","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਐਸੋ ਜਤਨ ਆਜੁ ਹਮ ਕਰਿ ਹੈ। ਨ੍ਰਿਪ ਗ੍ਰਿਹ ਰਾਖਿ ਜੋਗਿਯਹਿ ਮਰਿ ਹੈ। ੨੭।","roman":"Aiso jatan aaju ham kari hai | nrip grih raakhi jogiyhi mari hai | 27 |","meaning_en":"today we will make such an effort that the king is kept at home and the yogi dies.","page":1305,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":1305,"lines":[{"gurmukhi":"ਰਾਨੀ ਜੋ ਹੌ ਕਹੌ ਸੁ ਕਰਿਯਹੁ। ਰਾਜਾ ਜੂ ਤੇ ਨੈਕ ਨ ਡਰਿਯਹੁ।","roman":"Raanee jo hau kahau su kariyhu | raajaa joo te naik na dariyhu |","meaning_en":"Queen, do what I tell you; do not fear the king at all;","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਜੁਗਿਯਾ ਕਹ ਧਾਮ ਬੁਲੈਯਹੁ। ਲੌਨ ਡਾਰਿ ਭੂਅ ਮਾਝ ਗਡੈਯਹੁ। ੨੮।","roman":"Yaa jugiyaa kah dhaam bulaiyhu | laun daari bhooa maajh gadaiyhu | 28 |","meaning_en":"call this yogi to the palace, put in salt, and have him buried in the ground.\"","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[29],"number_text":"੨੯।","page":1305,"lines":[{"gurmukhi":"ਤਬ ਰਾਨੀ ਤਯੋ ਹੀ ਕਿਯੋ ਜੁਗਿਯਹਿ ਲਯੋ ਬੁਲਾਇ।","roman":"Tab raanee tayo hee kiyo jugiyhi layo bulaai |","meaning_en":"Then the queen did just that; she called the yogi,","page":1305,"meaning_status":"draft"},{"gurmukhi":"ਲੌਨ ਡਾਰਿ ਭੂਅ ਖੋਦਿ ਕੈ ਗਹਿ ਤਿਹ ਦਯੋ ਦਬਾਇ। ੨੯।","roman":"Laun daari bhooa khodi kai gahi tih dayo dabaai | 29 |","meaning_en":"and, digging the ground and putting in salt, she had him seized and pressed down into it.","page":1305,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1305,"meaning_status":"draft"},{"type":"verse","number":[30],"number_text":"੩੦।","page":1305,"lines":[{"gurmukhi":"ਜਾਇ ਨ੍ਰਿਪਤਿ ਪਤਿ ਬਚਨ ਉਚਾਰੇ। ਜੁਗਿਯ ਮਾਟੀ ਲਈ ਤਿਹਾਰੇ।","roman":"Jaai nripti pati bachan uchaare | jugiy maatee laee tihaare |","meaning_en":"She went and said to the lord of kings, \"Your yogi has taken to the earth;","page":1305,"meaning_status":"draft","note":"ਮਾਟੀ ਲਈ: lit. 'took the earth', i.e. died, was laid in the earth."},{"gurmukhi":"ਮਰਤੀ ਬਾਰ ਬਚਨ ਯੌ ਕਹਿਯੋ। ਸੋ ਮੈ ਦ੍ਰਿੜੁ ਕਰਿ ਜਿਯ ਮਹਿ ਗਹਿਯੋ। ੩੦।","roman":"Martee baar bachan yau kahiyo | so mai driru kari jiy mahi gahiyo | 30 |","meaning_en":"at his death he spoke these words, which I have held firmly in my heart:","page":1305,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":1307,"lines":[{"gurmukhi":"ਮੋਰੀ ਕਹੀ ਭੂਪ ਸੌ ਕਹਿਯਹੁ। ਤੁਮ ਬੈਠੇ ਗ੍ਰਿਹ ਹੀ ਮੈ ਰਹਿਯਹੁ।","roman":"Moree kahee bhoop sau kahiyhu | tum baithe grih hee mai rahiyhu |","meaning_en":"'Tell the king what I say: remain seated in your own home;","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਇਨ ਰਾਨਿਨ ਕੌ ਤਾਪੁ ਨ ਦੀਜਹੁ। ਰਾਜਿ ਜੋਗ ਦੋਨੋ ਹੀ ਕੀਜਹੁ। ੩੧।","roman":"In raanin kau taapu na deejhu | raaji jog dono hee keejhu | 31 |","meaning_en":"do not cause these queens pain; practise both kingship and yoga.'","page":1307,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":1307,"lines":[{"gurmukhi":"ਪੁਨਿ ਮੋ ਸੋ ਇਕ ਬਚਨ ਉਚਾਰੋ। ਜੌ ਨ੍ਰਿਪ ਕਹਿਯੋ ਨ ਕਰੈ ਤਿਹਾਰੋ।","roman":"Puni mo so ik bachan uchaaro | jau nrip kahiyo na karai tihaaro |","meaning_en":"Then he said one more thing to me: 'If the king does not do as you say,","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਪਾਛੇ ਯਹ ਬਚਨ ਉਚਰਿਯਹੁ। ਰਾਜਾ ਜੂ ਕੇ ਤਪ ਕਹ ਹਰਿਯਹੁ। ੩੨।","roman":"Tab paachhe yah bachan uchriyhu | raajaa joo ke tap kah hariyhu | 32 |","meaning_en":"then, after that, speak these words, and take away the king's austerity.'","page":1307,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":1307,"lines":[{"gurmukhi":"ਜੋ ਤਿਨ ਕਹੀ ਸੁ ਪਾਛੇ ਕਹਿ ਹੌ। ਤੁਮਰੇ ਸਕਲ ਭਰਮ ਕੋ ਦਹਿ ਹੌ।","roman":"Jo tin kahee su paachhe kahi hau | tumre sakal bharam ko dahi hau |","meaning_en":"What he said I will tell you later, and burn away all your doubts;","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਸੁਨਿ ਲੈ ਤੈ ਬਚਨ ਹਮਾਰੋ। ਜਾ ਤੇ ਰਹਿ ਹੈ ਰਾਜ ਤਿਹਾਰੋ। ੩੩।","roman":"Ab suni lai tai bachan hamaaro | jaa te rahi hai raaj tihaaro | 33 |","meaning_en":"now listen to my word, by which your kingdom will remain.","page":1307,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1307,"meaning_status":"draft"},{"type":"verse","number":[34],"number_text":"੩੪।","page":1307,"lines":[{"gurmukhi":"ਸੁਤ ਬਾਲਕ ਤਰੁਨੀ ਤ੍ਰਿਯਾ ਤੈ ਤ੍ਯਾਗਤ ਸਭ ਸਾਜ।","roman":"Sut baalak tarunee triyaa tai tyaagat sabh saaj |","meaning_en":"Young sons, a young wife: you are abandoning all these things;","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਬਿਧਿ ਕੀਯੋ ਕਸੂਤਿ ਗ੍ਰਿਹ ਕ੍ਯੋ ਕਰਿ ਰਹਸੀ ਰਾਜ। ੩੪।","roman":"Sabh bidhi keeyo kasooti grih kyo kari rahsee raaj | 34 |","meaning_en":"you have done every wrong to your house; how will the kingdom remain?","page":1307,"meaning_status":"draft","note":"ਕਸੂਤਿ: 'wrong, ill-doing'."}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":1307,"lines":[{"gurmukhi":"ਪੂਤ ਪਰੇ ਲੋਟਤ ਧਰਨਿ ਤ੍ਰਿਯਾ ਪਰੀ ਬਿਲਲਾਇ।","roman":"Poot pare lotat dharni triyaa paree billaai |","meaning_en":"Your sons lie rolling on the ground, your wife lies wailing;","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਬੰਧੁ ਭ੍ਰਿਤ ਰੋਦਨ ਕਰੈ ਰਾਜ ਬੰਸ ਤੇ ਜਾਇ। ੩੫।","roman":"Bandhu bhrit rodan karai raaj bans te jaai | 35 |","meaning_en":"kinsmen and servants weep; the kingdom is passing from the line.","page":1307,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1307,"meaning_status":"draft"},{"type":"verse","number":[36],"number_text":"੩੬।","page":1307,"lines":[{"gurmukhi":"ਚੇਲੇ ਸਭੈ ਅਨੰਦਿਤ ਭਏ। ਦੁਰਬਲ ਹੁਤੇ ਪੁਸਟ ਹ੍ਵੈ ਗਏ।","roman":"Chele sabhai anandit bhae | durbal hute pusat hvai gae |","meaning_en":"The disciples are all delighted; those who were thin have grown stout:","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਨਾਥ ਨ੍ਰਿਪਹਿ ਜੋਗੀ ਕਰਿ ਲਯੈ ਹੌ। ਦ੍ਵਾਰ ਦ੍ਵਾਰ ਕੇ ਟੂਕ ਮੰਗੈ ਹੈ। ੩੬।","roman":"Naath nriphi jogee kari layai hau | dvaar dvaar ke took mangai hai | 36 |","meaning_en":"'Our master will make the king a yogi, and make him beg scraps from door to door.'","page":1307,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1307,"meaning_status":"draft"},{"type":"verse","number":[37],"number_text":"੩੭।","page":1307,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਕਹ ਜੋਗੀ ਭੇਸ ਦੈ ਕਬ ਹੀ ਲਿਯੈ ਹੈ ਨਾਥ।","roman":"Nrip kah jogee bhes dai kab hee liyai hai naath |","meaning_en":"'When will the master take the king, giving him the yogi's garb?'","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਮੂਰਖ ਜਾਨੈ ਨਹੀ ਕਹਾ ਭਈ ਤਿਹ ਸਾਥ। ੩੭।","roman":"Yau moorakh jaanai nahee kahaa bhaee tih saath | 37 |","meaning_en":"So the fools think, not knowing what has happened to him.","page":1307,"meaning_status":"draft"}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":1307,"lines":[{"gurmukhi":"ਸੁਤ ਬਾਲਕ ਤਰੁਨੀ ਤ੍ਰਿਯਾ ਕ੍ਯੋ ਨ੍ਰਿਪ ਛਾਡਤ ਮੋਹਿ।","roman":"Sut baalak tarunee triyaa kyo nrip chhaadat mohi |","meaning_en":"Young sons, young wife: why do you leave me, O king?","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਚੇਰੀ ਸਭ ਰੋਦਨ ਕਰੈ ਦਯਾ ਨ ਉਪਜਤ ਤੋਹਿ। ੩੮।","roman":"Cheree sabh rodan karai dayaa na upjat tohi | 38 |","meaning_en":"All the maids are weeping; does no pity arise in you?\"","page":1307,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":1307,"lines":[{"gurmukhi":"ਸੁਨੁ ਰਾਨੀ ਤੋਸੋ ਕਹੋ ਬ੍ਰਹਮ ਗ੍ਯਾਨ ਕੋ ਭੇਦ।","roman":"Sunu raanee toso kaho braham gyaan ko bhed |","meaning_en":"\"Listen, queen, I tell you the secret of the knowledge of Brahm,","page":1307,"meaning_status":"draft","note":"Speaker not marked; from the sense, the king answers the queen."},{"gurmukhi":"ਜੁ ਕਛੁ ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤ ਕਹਤ ਔਰ ਉਚਾਰਤ ਬੇਦ। ੩੯।","roman":"Ju kachhu saasatr sinmrit kahat aur uchaarat bed | 39 |","meaning_en":"whatever the Shastras and Smritis say and the Vedas utter.","page":1307,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1307,"meaning_status":"draft"},{"type":"verse","number":[40],"number_text":"੪੦।","page":1307,"lines":[{"gurmukhi":"ਸੁਤ ਹਿਤ ਕੈ ਮਾਤਾ ਦੁਲਰਾਵੈ। ਕਾਲ ਮੂਡ ਪਰ ਦਾਂਤ ਬਜਾਵੈ।","roman":"Sut hit kai maataa dulraavai | kaal mood par daant bajaavai |","meaning_en":"A mother fondles her son out of love, while Death gnashes his teeth over her head;","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਵੁਹ ਨਿਤ ਲਖੇ ਪੂਤ ਬਢਿ ਜਾਵਤ। ਲੈਨ ਨ ਮੂੜ ਕਾਲ ਨਿਜਕਾਵਤ। ੪੦।","roman":"Vuh nit lakhe poot badhi jaavat | lain na moor kaal nijkaavat | 40 |","meaning_en":"she sees her son growing every day; the fool does not see Death drawing near to take him.","page":1307,"meaning_status":"draft","note":"ਨਿਜਕਾਵਤ: read as 'drawing near' (nazdik); uncertain. 'See' is carried over from the first half of the line."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1307,"meaning_status":"draft"},{"type":"verse","number":[41],"number_text":"੪੧।","page":1307,"lines":[{"gurmukhi":"ਕੋ ਮਾਤਾ ਬਨਿਤਾ ਸੁਤਾ ਪਾਚ ਤਤ ਕੀ ਦੇਹ।","roman":"Ko maataa banitaa sutaa paach tat kee deh |","meaning_en":"Who is mother, wife or daughter? The body is made of five elements;","page":1307,"meaning_status":"draft"},{"gurmukhi":"ਦਿਵਸ ਚਾਰ ਕੋ ਪੇਖਨੋ ਅੰਤ ਖੇਹ ਕੀ ਖੇਹ। ੪੧।","roman":"Divas chaar ko pekhno ant kheh kee kheh | 41 |","meaning_en":"it is a show of four days, and in the end dust to dust.","page":1307,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1309,"meaning_status":"draft"},{"type":"verse","number":[42],"number_text":"੪੨।","page":1309,"lines":[{"gurmukhi":"ਪ੍ਰਾਨੀ ਜਨਮ ਪ੍ਰਥਮ ਜਬ ਆਵੈ। ਬਾਲਾਪਨ ਮੈ ਜਨਮੁ ਗਵਾਵੈ।","roman":"Praanee janam pratham jab aavai | baalaapan mai janmu gavaavai |","meaning_en":"When a creature first comes to birth, he wastes his life in childhood;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਤਰੁਨਾਪਨ ਬਿਖਿਯਨ ਕੈ ਕੀਨੋ। ਕਬਹੁ ਨ ਬ੍ਰਹਮ ਤਤੁ ਕੋ ਚੀਨੋ। ੪੨।","roman":"Tarunaapan bikhiyan kai keeno | kabhu na braham tatu ko cheeno | 42 |","meaning_en":"his youth he gives to the pleasures of the senses, and never recognises the essence of Brahm.","page":1309,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1309,"meaning_status":"draft"},{"type":"verse","number":[43],"number_text":"੪੩।","page":1309,"lines":[{"gurmukhi":"ਬਿਰਧ ਭਏ ਤਨੁ ਕਾਪਈ ਨਾਮੁ ਨ ਜਪਿਯੋ ਜਾਇ।","roman":"Biradh bhae tanu kaapaee naamu na japiyo jaai |","meaning_en":"When he grows old the body trembles and the Name cannot be repeated;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨਾ ਭਜਨ ਭਗਵਾਨ ਕੇ ਪਾਪ ਗ੍ਰਿਹਤ ਤਨ ਆਇ। ੪੩।","roman":"Binaa bhajan bhagvaan ke paap grihat tan aai | 43 |","meaning_en":"without worship of the Lord, sin comes and seizes the body.","page":1309,"meaning_status":"draft","note":"ਗ੍ਰਿਹਤ: read as 'seizes' (grahat)."}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":1309,"lines":[{"gurmukhi":"ਮਿਰਤੁ ਲੋਕ ਮੈ ਆਇ ਕੈ ਬਾਲ ਬ੍ਰਿਧ ਕੋਊ ਹੋਇ।","roman":"Mirtu lok mai aai kai baal bridh ko'oo hoi |","meaning_en":"Having come into this world of death, be one a child or an old man,","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਊਚ ਨੀਚ ਰਾਜਾ ਪ੍ਰਜਾ ਜਿਯਤ ਨ ਰਹਸੀ ਕੋਇ। ੪੪।","roman":"Ooch neech raajaa prajaa jiyat na rahsee koi | 44 |","meaning_en":"high or low, king or subject, no one shall remain alive.\"","page":1309,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":1309,"lines":[{"gurmukhi":"ਰਾਨੀ ਐਸੇ ਬਚਨ ਸੁਨਿ ਭੂਮਿ ਪਰੀ ਮੁਰਛਾਇ।","roman":"Raanee aise bachan suni bhoomi paree murchhaai |","meaning_en":"Hearing such words the queen fell to the ground in a swoon;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਪੋਸਤਿਯਾ ਕੀ ਨੀਦ ਜ੍ਯੋ ਸੋਇ ਨ ਸੋਯੋ ਜਾਇ। ੪੫।","roman":"Postiyaa kee need jyo soi na soyo jaai | 45 |","meaning_en":"like the sleep of an opium-eater, she slept and yet could not sleep.","page":1309,"meaning_status":"draft","note":"ਪੋਸਤਿਯਾ: one addicted to poppy-husk. ਸੋਇ ਨ ਸੋਯੋ ਜਾਇ: 'sleeping, yet unable to sleep'; sense somewhat uncertain."}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":1309,"lines":[{"gurmukhi":"ਜੋ ਉਪਜਿਯੋ ਸੋ ਬਿਨਸਿ ਹੈ ਜਗ ਰਹਿਬੋ ਦਿਨ ਚਾਰਿ।","roman":"Jo upjiyo so binsi hai jag rahibo din chaari |","meaning_en":"\"Whatever is born will perish; the stay in the world is four days;","page":1309,"meaning_status":"draft","note":"Speaker not marked; taken as the king continuing."},{"gurmukhi":"ਸੁਤ ਬਨਿਤਾ ਦਾਸੀ ਕਹਾ ਦੇਖਹੁ ਤਤੁ ਬੀਚਾਰਿ। ੪੬।","roman":"Sut banitaa daasee kahaa dekhhu tatu beechaari | 46 |","meaning_en":"what are sons, wife and maids? Consider the essence and see.\"","page":1309,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1309,"meaning_status":"draft"},{"type":"verse","number":[47],"number_text":"੪੭।","page":1309,"lines":[{"gurmukhi":"ਪਤਿ ਪੂਤਨ ਤੇ ਰਹੈ ਬਿਜੈ ਪੂਤਨ ਤੇ ਪੈਯੈ।","roman":"Pati pootan te rahai bijai pootan te paiyai |","meaning_en":"\"Honour is kept through sons; victory is won through sons;","page":1309,"meaning_status":"draft","note":"Speaker not marked; from the sense, the queen replies."},{"gurmukhi":"ਦਿਰਬੁ ਕਪੂਤਨ ਜਾਇ ਰਾਜ ਸਪੂਤਨੁ ਬਹੁਰੈਯੈ।","roman":"Dirbu kapootan jaai raaj sapootnu bahuraiyai |","meaning_en":"wealth is lost through bad sons; good sons bring the kingdom back;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਪਿੰਡ ਪੁਤ੍ਰ ਹੀ ਦੇਹਿ ਪ੍ਰੀਤਿ ਪੂਤੋ ਉਪਜਾਵਹਿ।","roman":"Pind putr hee dehi preeti pooto upjaavhi |","meaning_en":"it is sons who offer the funeral rice-balls; sons give rise to love;","page":1309,"meaning_status":"draft","note":"ਪਿੰਡ: the rice-balls offered to the departed."},{"gurmukhi":"ਬਹੁਤ ਦਿਨਨ ਕੋ ਬੈਰ ਗਯੋ ਪੂਤੈ ਬਹੁਰਾਵਹਿ।","roman":"Bahut dinan ko bair gayo pootai bahuraavhi |","meaning_en":"an enmity of many days gone by, it is sons who repay it.","page":1309,"meaning_status":"draft","note":"ਬਹੁਰਾਵਹਿ: lit. 'bring back', i.e. avenge."},{"gurmukhi":"ਜੋ ਪੂਤਨ ਕੌ ਛਾਡਿ ਨ੍ਰਿਪਤਿ ਤਪਸ੍ਯਾ ਕੋ ਜਾਵੈ।","roman":"Jo pootan kau chhaadi nripti tapsyaa ko jaavai |","meaning_en":"The king who leaves his sons and goes off to do austerities","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਪਰੈ ਨਰਕ ਸੋ ਜਾਇ ਅਧਿਕ ਤਨ ਮੈ ਦੁਖ ਪਾਵੈ। ੪੭।","roman":"Parai narak so jaai adhik tan mai dukh paavai | 47 |","meaning_en":"falls into hell and suffers great pain in his body.\"","page":1309,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":1309,"lines":[{"gurmukhi":"ਨ ਕੋ ਹਮਾਰੋ ਪੂਤ ਨ ਕੋ ਹਮਰੀ ਕੋਈ ਨਾਰੀ।","roman":"Na ko hamaaro poot na ko hamree koee naaree |","meaning_en":"\"No one is my son, no one is my wife;","page":1309,"meaning_status":"draft","note":"Speaker not marked; from the sense, the king replies."},{"gurmukhi":"ਨ ਕੋ ਹਮਾਰੋ ਪਿਤਾ ਨ ਕੋ ਹਮਰੀ ਮਹਤਾਰੀ।","roman":"Na ko hamaaro pitaa na ko hamree mahtaaree |","meaning_en":"no one is my father, no one is my mother;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਨ ਕੋ ਹਮਰੀ ਭੈਨ ਨ ਕੋ ਹਮਰੋ ਕੋਈ ਭਾਈ।","roman":"Na ko hamree bhain na ko hamro koee bhaaee |","meaning_en":"no one is my sister, no one is my brother;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਨ ਕੋ ਹਮਾਰੋ ਦੇਸ ਨ ਹੌ ਕਾਹੂ ਕੌ ਰਾਈ।","roman":"Na ko hamaaro des na hau kaahoo kau raaee |","meaning_en":"no country is mine, nor am I anyone's king.","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਿਥਾ ਜਗਤ ਮੈ ਆਇ ਜੋਗ ਬਿਨੁ ਜਨਮੁ ਗਵਾਯੋ।","roman":"Brithaa jagat mai aai jog binu janmu gavaayo |","meaning_en":"Having come into the world, I have wasted my birth in vain without yoga;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਤਜ੍ਯੋ ਰਾਜ ਅਰੁ ਪਾਟ ਯਹੈ ਜਿਯਰੇ ਮੁਹਿ ਭਾਯੋ। ੪੮।","roman":"Tajyo raaj aru paat yahai jiyre muhi bhaayo | 48 |","meaning_en":"to give up kingdom and throne: this is what pleases my heart.","page":1309,"meaning_status":"draft"}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":1309,"lines":[{"gurmukhi":"ਜਨਨਿ ਜਠਰ ਮਹਿ ਆਇ ਪੁਰਖ ਬਹੁਤੋ ਦੁਖੁ ਪਾਵਹਿ।","roman":"Janni jathar mahi aai purakh bahuto dukhu paavhi |","meaning_en":"Coming into the mother's womb, a man suffers much pain;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਮੂਤ੍ਰ ਧਾਮ ਕੌ ਪਾਇ ਕਹਤ ਹਮ ਭੋਗ ਕਮਾਵਹਿ।","roman":"Mootr dhaam kau paai kahat ham bhog kamaavhi |","meaning_en":"obtaining the place of urine, he says, 'I am enjoying pleasure';","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਥੂਕ ਤ੍ਰਿਯਾ ਕੌ ਚਾਟਿ ਕਹਤ ਅਧਰਾਮ੍ਰਿਤ ਪਾਯੋ।","roman":"Thook triyaa kau chaati kahat adhraamrit paayo |","meaning_en":"licking a woman's spittle, he says, 'I have obtained the nectar of the lips';","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਿਥਾ ਜਗਤ ਮੈ ਜਨਮੁ ਬਿਨਾ ਜਗਦੀਸ ਗਵਾਯੋ। ੪੯।","roman":"Brithaa jagat mai janmu binaa jagdees gavaayo | 49 |","meaning_en":"in vain he wastes his birth in the world, without the Lord of the world.\"","page":1309,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਾਨੀ ਬਾਚ","gurmukhi":"ਰਾਨੀ ਬਾਚ","roman":"Raanee baach","meaning_en":"The queen said:","page":1309,"meaning_status":"draft"},{"type":"verse","number":[50],"number_text":"੫੦।","page":1309,"lines":[{"gurmukhi":"ਰਿਖਿ ਯਾਹੀ ਤੇ ਭਏ ਨ੍ਰਿਪਤਿ ਯਾਹੀ ਉਪਜਾਏ।","roman":"Rikhi yaahee te bhae nripti yaahee upjaae |","meaning_en":"\"From this very place the sages were born; from this the kings were brought forth;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਯਾਸਾਦਿਕ ਸਭ ਚਤੁਰ ਇਹੀ ਮਾਰਗ ਹ੍ਵੈ ਆਏ।","roman":"Byaasaadik sabh chatur ihee maarag hvai aae |","meaning_en":"Vyas and all the wise came by this very path;","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਪਰਸੇ ਯਾ ਕੇ ਬਿਨਾ ਕਹੋ ਜਗ ਮੈ ਕੋ ਆਯੋ।","roman":"Parse yaa ke binaa kaho jag mai ko aayo |","meaning_en":"without touching it, say, who has come into the world?","page":1309,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਥਮ ਐਤ ਭਵ ਪਾਇ ਬਹੁਰਿ ਪਰਮੇਸ੍ਵਰ ਪਾਯੋ। ੫੦।","roman":"Pratham ait bhav paai bahuri parmesvar paayo | 50 |","meaning_en":"First obtaining birth this way, one has afterwards obtained the Supreme Lord.\"","page":1309,"meaning_status":"draft","note":"ਐਤ ਭਵ: read as 'birth by this way/here'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[51],"number_text":"੫੧।","page":1311,"lines":[{"gurmukhi":"ਅਤਿ ਚਾਤੁਰਿ ਰਾਨੀ ਸੁਮਤਿ ਬਾਤੈ ਕਹੀ ਅਨੇਕ।","roman":"Ati chaaturi raanee sumti baatai kahee anek |","meaning_en":"The very clever and wise queen said many things;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਰੋਗੀ ਕੇ ਪਥ ਜ੍ਯੋ ਨ੍ਰਿਪਤਿ ਮਾਨਤ ਭਯੋ ਨ ਏਕ। ੫੧।","roman":"Rogee ke path jyo nripti maanat bhayo na ek | 51 |","meaning_en":"but like a sick man with his diet, the king accepted not one.","page":1311,"meaning_status":"draft","note":"ਪਥ: the regimen (pathya) prescribed to a patient."}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਬਾਚ","gurmukhi":"ਰਾਜਾ ਬਾਚ","roman":"Raajaa baach","meaning_en":"The king said:","page":1311,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[52],"number_text":"੫੨।","page":1311,"lines":[{"gurmukhi":"ਪੁਨਿ ਰਾਜੈ ਯੌ ਕਹੀ ਬਚਨ ਸੁਨ ਮੇਰੋ ਰਾਨੀ।","roman":"Puni raajai yau kahee bachan sun mero raanee |","meaning_en":"Then the king spoke thus: \"Hear my word, queen;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਬ੍ਰਹਮ ਗ੍ਯਾਨ ਕੀ ਬਾਤ ਕਛੂ ਤੈ ਨੈਕੁ ਨ ਜਾਨੀ।","roman":"Braham gyaan kee baat kachhoo tai naiku na jaanee |","meaning_en":"you have not understood the least thing of the knowledge of Brahm.","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਬਾਪੁਰੀ ਤ੍ਰਿਯਾ ਨੇਹ ਜਾ ਸੌ ਅਤਿ ਕਰਿ ਹੈ।","roman":"Kahaa baapuree triyaa neh jaa sau ati kari hai |","meaning_en":"What is a poor woman, whom a man loves so much?","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਮੂਤ੍ਰ ਕੋ ਧਾਮ ਬਿਹਸਿ ਆਗੇ ਤਿਹ ਧਰਿ ਹੈ। ੫੨।","roman":"Mahaa mootr ko dhaam bihsi aage tih dhari hai | 52 |","meaning_en":"Laughing, she sets before him the great house of urine.\"","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[53],"number_text":"੫੩।","page":1311,"lines":[{"gurmukhi":"ਪੁਨਿ ਰਾਜੈ ਐਸੇ ਕਹਿਯੋ ਸੁਨੁ ਹੋ ਰਾਜ ਕੁਮਾਰਿ।","roman":"Puni raajai aise kahiyo sunu ho raaj kumaari |","meaning_en":"Then the king spoke thus: \"Listen, princess;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਜੋਗੀ ਤੁਮ ਸੌ ਕਹਿਯੋ ਸੋ ਮੁਹਿ ਕਹੌ ਸੁਧਾਰਿ। ੫੩।","roman":"Jo jogee tum sau kahiyo so muhi kahau sudhaari | 53 |","meaning_en":"what the yogi said to you, tell it to me correctly.\"","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[54],"number_text":"੫੪।","page":1311,"lines":[{"gurmukhi":"ਦੁਤਿਯ ਬਚਨ ਜੋਗੀ ਜੋ ਕਹਿਯੋ। ਸੋ ਮੈ ਹ੍ਰਿਦੈ ਬੀਚ ਦ੍ਰਿੜ ਗਹਿਯੋ।","roman":"Dutiy bachan jogee jo kahiyo | so mai hridai beech drir gahiyo |","meaning_en":"\"The second thing the yogi said, I have held firm in my heart;","page":1311,"meaning_status":"draft","note":"Speaker not marked; the queen answers."},{"gurmukhi":"ਜੋ ਤੁਮ ਕਹੌ ਸੁ ਬਚਨ ਬਖਾਨੋ। ਤੁਮ ਜੋ ਸਾਚੁ ਜਾਨਿ ਜਿਯ ਮਾਨੋ। ੫੪।","roman":"Jo tum kahau su bachan bakhaano | tum jo saachu jaani jiy maano | 54 |","meaning_en":"if you say so, I will tell those words; know them as true and accept them in your heart.","page":1311,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":1311,"lines":[{"gurmukhi":"ਮੰਦਰ ਏਕ ਉਜਾਰ ਉਸਰਿਯਹੁ। ਬੈਠੇ ਤਹਾ ਤਪਸ੍ਯਾ ਕਰਿਯਹੁ।","roman":"Mandar ek ujaar usriyhu | baithe tahaa tapsyaa kariyhu |","meaning_en":"'Raise a mansion in a desolate place; sit there and practise austerities;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਹੌ ਤਹ ਔਰ ਮੂਰਤਿ ਧਰ ਐਹੋ। ਬ੍ਰਹਮ ਗ੍ਯਾਨ ਨ੍ਰਿਪ ਕੋ ਸਮੁਝੈਹੋ। ੫੫।","roman":"Hau tah aur moorti dhar aiho | braham gyaan nrip ko samujhaiho | 55 |","meaning_en":"I will come there taking another form, and explain the knowledge of Brahm to the king.","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[56],"number_text":"੫੬।","page":1311,"lines":[{"gurmukhi":"ਬਾਨੀ ਤਹਾ ਅਕਾਸ ਕੀ ਹ੍ਵੈ ਹੈ ਤੁਮੈ ਬਨਾਇ।","roman":"Baanee tahaa akaas kee hvai hai tumai banaai |","meaning_en":"A voice from the sky will surely come to you there;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਤੁਮ ਸਤਿ ਪਛਾਨਿਯੋ ਜੋਗੀ ਪਹੁਚ੍ਯੋ ਆਇ। ੫੬।","roman":"Tab tum sati pachhaaniyo jogee pahuchyo aai | 56 |","meaning_en":"then recognise it as true that the yogi has arrived.'\"","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[57],"number_text":"੫੭।","page":1311,"lines":[{"gurmukhi":"ਰਾਨੀ ਬਨ ਮੈ ਸਦਨ ਸਵਾਰਿਯੋ। ਛਾਤ ਬੀਚ ਰੌਜਨ ਇਕ ਧਾਰਿਯੋ।","roman":"Raanee ban mai sadan savaariyo | chhaat beech raujan ik dhaariyo |","meaning_en":"The queen prepared a house in the forest, and made an opening in the roof,","page":1311,"meaning_status":"draft","note":"ਰੌਜਨ: Persian 'rauzan', an opening or small window; here a hidden recess in the roof."},{"gurmukhi":"ਜਾ ਕੇ ਬਿਖੇ ਮਨੁਖ ਛਪਿ ਰਹੈ। ਜੋ ਚਾਹੈ ਚਿਤ ਮੈ ਸੋ ਕਹੈ। ੫੭।","roman":"Jaa ke bikhe manukh chhapi rahai | jo chaahai chit mai so kahai | 57 |","meaning_en":"in which a man could stay hidden and say whatever he wished.","page":1311,"meaning_status":"draft"}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":1311,"lines":[{"gurmukhi":"ਬੈਠੇ ਤਰੇ ਨਜਰਿ ਨਹਿ ਆਵੈ। ਬਾਨੀ ਨਭਹੀ ਕੀ ਲਖਿ ਜਾਵੈ।","roman":"Baithe tare najri nahi aavai | baanee nabhhee kee lakhi jaavai |","meaning_en":"To those sitting below he would not be visible; it would be taken for a voice from the sky.","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਰਾਨੀ ਤਹਾ ਪੁਰਖ ਬੈਠਾਯੋ। ਅਮਿਤ ਦਰਬੁ ਦੈ ਤਾਹਿ ਸਿਖਾਯੋ। ੫੮।","roman":"Raanee tahaa purakh baithaayo | amit darbu dai taahi sikhaayo | 58 |","meaning_en":"The queen seated a man there; giving him untold wealth, she coached him.","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[59],"number_text":"੫੯।","page":1311,"lines":[{"gurmukhi":"ਏਕ ਪੁਰਖ ਚਾਕਰ ਹੁਤੋ ਨਾਮ ਸਿੰਘ ਆਨੂਪ।","roman":"Ek purakh chaakar huto naam singh aanoop |","meaning_en":"There was a man, a servant, named Anup Singh;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਵਹਿ ਜੁਗਿਯਾ ਕੀ ਬੈਸ ਥੋ ਤਾ ਕੀ ਸਕਲ ਸਰੂਪ। ੫੯।","roman":"Vahi jugiyaa kee bais tho taa kee sakal saroop | 59 |","meaning_en":"he was of the yogi's age, and his whole likeness.","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1311,"meaning_status":"draft"},{"type":"verse","number":[60],"number_text":"੬੦।","page":1311,"lines":[{"gurmukhi":"ਤਾ ਸੌ ਕਹਿਯੋ ਨ੍ਰਿਪਹਿ ਸਮੁਝੈਯਹੁ। ਤੁਮ ਜੋਗੀ ਆਪਹਿ ਠਹਿਰੈਯਹੁ।","roman":"Taa sau kahiyo nriphi samujhaiyhu | tum jogee aaphi thahiraiyhu |","meaning_en":"She said to him, \"Persuade the king; pass yourself off as the yogi;","page":1311,"meaning_status":"draft"},{"gurmukhi":"ਕ੍ਯੋ ਹੂੰ ਨ੍ਰਿਪਹਿ ਮੋਰਿ ਘਰ ਲ੍ਯਾਵਹੁ। ਜੋ ਕਛੁ ਮੁਖ ਮਾਗਹੁ ਸੋ ਪਾਵਹੁ। ੬੦।","roman":"Kyo hoon nriphi mori ghar lyaavhu | jo kachhu mukh maaghu so paavhu | 60 |","meaning_en":"somehow bring the king back to my house, and you shall have whatever you ask.\"","page":1311,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1313,"meaning_status":"draft"},{"type":"verse","number":[61],"number_text":"੬੧।","page":1313,"lines":[{"gurmukhi":"ਜਬ ਤਾ ਸੋ ਐਸੋ ਬਚਨ ਰਾਨੀ ਕਹਿਯੋ ਬੁਲਾਇ।","roman":"Jab taa so aiso bachan raanee kahiyo bulaai |","meaning_en":"When the queen called him and spoke such words to him,","page":1313,"meaning_status":"draft"},{"gurmukhi":"ਚਤੁਰ ਪੁਰਖੁ ਆਗੇ ਹੁਤੋ ਸਕਲ ਭੇਦ ਗਯੋ ਪਾਇ। ੬੧।","roman":"Chatur purkhu aage huto sakal bhed gayo paai | 61 |","meaning_en":"he was already a clever man, and grasped the whole secret.","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1313,"meaning_status":"draft"},{"type":"verse","number":[62],"number_text":"੬੨।","page":1313,"lines":[{"gurmukhi":"ਤਬ ਰਾਨੀ ਰਾਜਾ ਪਹਿ ਆਈ। ਲੀਨੇ ਦ੍ਵੈ ਕੰਥਾ ਕਰਵਾਈ।","roman":"Tab raanee raajaa pahi aaee | leene dvai kanthaa karvaaee |","meaning_en":"Then the queen came to the king, having had two patched cloaks made:","page":1313,"meaning_status":"draft","note":"ਕੰਥਾ: the patched cloak of an ascetic."},{"gurmukhi":"ਇਕ ਤੁਮ ਧਰੋ ਏਕ ਹੌ ਧਰਿ ਹੋ। ਤੁਮਰੇ ਸੰਗ ਤਪਸ੍ਯਾ ਕਰਿਹੋ। ੬੨।","roman":"Ik tum dharo ek hau dhari ho | tumre sang tapsyaa kariho | 62 |","meaning_en":"\"You wear one and I will wear one; I will practise austerities with you.\"","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1313,"meaning_status":"draft"},{"type":"verse","number":[63],"number_text":"੬੩।","page":1313,"lines":[{"gurmukhi":"ਜਬ ਰਾਨੀ ਐਸੇ ਕਹਿਯੋ ਤਬ ਰਾਜੈ ਮੁਸਕਾਇ।","roman":"Jab raanee aise kahiyo tab raajai muskaai |","meaning_en":"When the queen spoke thus, the king smiled;","page":1313,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਤਾ ਸੋ ਬਾਤੈ ਕਰੀ ਸੋ ਤੁਹਿ ਕਹੋ ਸੁਨਾਇ। ੬੩।","roman":"Jo taa so baatai karee so tuhi kaho sunaai | 63 |","meaning_en":"the words he spoke to her, I tell you.","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1313,"meaning_status":"draft"},{"type":"verse","number":[64],"number_text":"੬੪।","page":1313,"lines":[{"gurmukhi":"ਹੈ ਬਨ ਕੋ ਬਸਿਬੋ ਦੁਖ ਕੋ ਕਹੁ ਸੁੰਦਰਿ ਤੂ ਸੰਗ ਕਹਿਯੋ ਨਿਬਹੈ ਹੈ।","roman":"Hai ban ko basibo dukh ko kahu sundri too sang kahiyo nibhai hai |","meaning_en":"\"Dwelling in the forest is painful; say, fair one, how will you last it out with me?","page":1313,"meaning_status":"draft","note":"ਕਹਿਯੋ: read here as 'how'; uncertain."},{"gurmukhi":"ਸੀਤ ਤੁਸਾਰ ਪਰੈ ਤਨ ਪੈ ਸੁ ਇਤੋ ਤਬ ਤੌ ਹਠਹੂੰ ਨ ਗਹੈ ਹੈ।","roman":"Seet tusaar parai tan pai su ito tab tau hathhoon na gahai hai |","meaning_en":"Cold and frost will fall on your body; then you will not hold to such obstinacy.","page":1313,"meaning_status":"draft"},{"gurmukhi":"ਸਾਲ ਤਮਾਲ ਬਡੇ ਜਹ ਬ੍ਯਾਲ ਨਿਹਾਲ ਤਿਨੈ ਬਹੁਧਾ ਬਿਲਲੈ ਹੈ।","roman":"Saal tamaal bade jah byaal nihaal tinai bahudhaa billai hai |","meaning_en":"Where there are great sal and tamal trees and snakes, seeing them you will wail much.","page":1313,"meaning_status":"draft"},{"gurmukhi":"ਤੂ ਸੁਕਮਾਰਿ ਕਰੀ ਕਰਤਾਰ ਸੁ ਹਾਰਿ ਪਰੇ ਤੁਹਿ ਕੌਨ ਉਠੈ ਹੈ। ੬੪।","roman":"Too sukmaari karee kartaar su haari pare tuhi kaun uthai hai | 64 |","meaning_en":"The Creator made you delicate; when you fall exhausted, who will lift you up?\"","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਾਨੀ ਬਾਚ","gurmukhi":"ਰਾਨੀ ਬਾਚ","roman":"Raanee baach","meaning_en":"The queen said:","page":1313,"meaning_status":"draft"},{"type":"verse","number":[65],"number_text":"੬੫।","page":1313,"lines":[{"gurmukhi":"ਸੀਤ ਸਮੀਰ ਸਹੌ ਤਨ ਪੈ ਸੁਨੁ ਨਾਥ ਤੁਮੈ ਅਬ ਛਾਡਿ ਨ ਜੈਹੋ।","roman":"Seet sameer sahau tan pai sunu naath tumai ab chhaadi na jaiho |","meaning_en":"\"I will bear the cold wind on my body; listen, lord, I will not leave you now.","page":1313,"meaning_status":"draft"},{"gurmukhi":"ਸਾਲ ਤਮਾਲ ਬਡੇ ਜਹ ਬ੍ਯਾਲ ਨਿਹਾਲ ਤਿਨੈ ਕਛੁ ਨ ਡਰ ਪੈਹੋ।","roman":"Saal tamaal bade jah byaal nihaal tinai kachhu na dar paiho |","meaning_en":"Where there are great sal and tamal trees and snakes, seeing them I will feel no fear.","page":1313,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਤਜੋ ਸਜ ਸਾਜ ਤਪੋ ਧਨ ਲਾਜ ਧਰੇ ਪ੍ਰਭ ਸੰਗ ਸਿਧੈ ਹੋ।","roman":"Raaj tajo saj saaj tapo dhan laaj dhare prabh sang sidhai ho |","meaning_en":"I will give up the kingdom, put on the ascetic's array, and keeping my honour go with my lord.","page":1313,"meaning_status":"draft","note":"ਤਪੋ ਧਨ: 'one whose wealth is austerity', an ascetic. Division of the phrase uncertain."},{"gurmukhi":"ਬਾਤ ਇਹੈ ਦੁਖ ਗਾਤ ਸਹੋ ਬਨ ਨਾਯਕ ਕੇ ਸੰਗ ਪਾਤ ਚਬੈਹੋ। ੬੫।","roman":"Baat ihai dukh gaat saho ban naayak ke sang paat chabaiho | 65 |","meaning_en":"This is my word: I will bear pain on my body, and chew leaves in the forest with my husband.\"","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਬਾਚ","gurmukhi":"ਰਾਜਾ ਬਾਚ","roman":"Raajaa baach","meaning_en":"The king said:","page":1313,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1313,"meaning_status":"draft"},{"type":"verse","number":[66],"number_text":"੬੬।","page":1313,"lines":[{"gurmukhi":"ਰਾਜ ਭਲੀ ਬਿਧ ਰਾਖਿਯਹੁ ਨਾਥ ਸੰਭਰਿਯਹੁ ਨਿਤ।","roman":"Raaj bhalee bidh raakhiyhu naath sanbhriyhu nit |","meaning_en":"\"Keep the kingdom well, and remember the Lord always;","page":1313,"meaning_status":"draft","note":"ਨਾਥ: taken as 'the Lord'; could be 'your lord (husband)'."},{"gurmukhi":"ਸੁਤ ਸੇਵਾ ਨਿਤ ਕੀਜਿਯਹੁ ਬਚਨ ਧਾਰਿਯਹੁ ਚਿਤ। ੬੬।","roman":"Sut sevaa nit keejiyhu bachan dhaariyhu chit | 66 |","meaning_en":"care for our son always; keep my word in your mind.","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1313,"meaning_status":"draft"},{"type":"verse","number":[67],"number_text":"੬੭।","page":1313,"lines":[{"gurmukhi":"ਰਾਜ ਤਜੋ ਸਜਿ ਸਾਜ ਤਪੋ ਧਨ ਕਾਜ ਨ ਬਾਸਵ ਕੀ ਠਕੁਰਾਈ।","roman":"Raaj tajo saji saaj tapo dhan kaaj na baasav kee thakuraaee |","meaning_en":"I give up the kingdom and put on the ascetic's array; I have no use for Indra's lordship;","page":1313,"meaning_status":"draft","note":"ਬਾਸਵ: Indra."},{"gurmukhi":"ਅਸ੍ਵ ਪਦਾਤੁ ਬਨੈ ਬਨ ਬਾਰੁਣ ਚਾਹਤ ਹੌ ਨ ਕਛੂ ਪ੍ਰਭਤਾਈ।","roman":"Asv padaatu banai ban baarun chaahat hau na kachhoo prabhtaaee |","meaning_en":"horses, foot-soldiers, elephants: I want no such greatness at all;","page":1313,"meaning_status":"draft","note":"ਬਨੈ ਬਨ ਬਾਰੁਣ: read as 'fine elephants' (varan); ਬਨੈ ਬਨ uncertain."},{"gurmukhi":"ਬਾਲਕ ਬਾਰ ਤਜੇ ਬਰ ਨਾਰਿ ਤਜੋ ਅਸੁਰਾਰਿ ਯਹੈ ਠਹਰਾਈ।","roman":"Baalak baar taje bar naari tajo asuraari yahai thahraaee |","meaning_en":"I leave my children and I leave my fair wife; I have fixed on the Enemy of demons alone;","page":1313,"meaning_status":"draft","note":"ਅਸੁਰਾਰਿ: 'enemy of the demons', the Lord."},{"gurmukhi":"ਜਾਇ ਬਸੋ ਬਨ ਮੈ ਸੁਖੁ ਸੋ ਸੁਨੁ ਸੁੰਦਰਿ ਆਜੁ ਇਹੈ ਮਨ ਭਾਈ। ੬੭।","roman":"Jaai baso ban mai sukhu so sunu sundri aaju ihai man bhaaee | 67 |","meaning_en":"I will go and dwell in the forest in peace; listen, fair one, today this pleases my mind.\"","page":1313,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1315,"meaning_status":"draft"},{"type":"verse","number":[68],"number_text":"੬੮।","page":1315,"lines":[{"gurmukhi":"ਜੋ ਇਸਤ੍ਰੀ ਪਤਿ ਛਾਡਿ ਕੈ ਬਸਤ ਧਾਮ ਕੇ ਮਾਹਿ।","roman":"Jo istree pati chhaadi kai basat dhaam ke maahi |","meaning_en":"\"The woman who leaves her husband and stays in the house","page":1315,"meaning_status":"draft","note":"Printed before the heading 'The queen said'; from the sense it is the queen's argument."},{"gurmukhi":"ਤਿਨ ਕੋ ਆਗੇ ਸ੍ਵਰਗ ਕੇ ਭੀਤਰਿ ਪੈਠਬ ਨਾਹਿ। ੬੮।","roman":"Tin ko aage svarag ke bheetri paithab naahi | 68 |","meaning_en":"has no entry into heaven hereafter.\"","page":1315,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਾਨੀ ਬਾਚ","gurmukhi":"ਰਾਨੀ ਬਾਚ","roman":"Raanee baach","meaning_en":"The queen said:","page":1315,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":1315,"meaning_status":"draft"},{"type":"verse","number":[69],"number_text":"੬੯।","page":1315,"lines":[{"gurmukhi":"ਬਾਲਕਨ ਬੋਰੋ ਰਾਜ ਇੰਦ੍ਰਹੂੰ ਕੋ ਛੋਰੋ","roman":"Baalkan boro raaj indrahoon ko chhoro","meaning_en":"\"I will forsake the children, give up even Indra's kingdom,","page":1315,"meaning_status":"draft","note":"ਬੋਰੋ: lit. 'drown', i.e. cast off."},{"gurmukhi":"ਔਰ ਭੂਖਨਨ ਤੋਰੋ ਕਠਿਨਾਈ ਐਸੀ ਝਲਿਹੋ।","roman":"Aur bhookhnan toro kathinaaee aisee jhaliho |","meaning_en":"break my ornaments, and bear such hardship;","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਪਾਤ ਫਲ ਖੈਹੋ ਸਿੰਘ ਸਾਂਪ ਤੇ ਡਰੈਹੋ ਨਾਹਿ","roman":"Paat phal khaiho singh saanp te daraiho naahi","meaning_en":"I will eat leaves and fruit, and not fear lion or snake;","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨਾ ਪ੍ਰਾਨ ਪ੍ਯਾਰੇ ਕੇ ਹਿਮਾਚਲ ਮੈ ਗਲਿਹੋ।","roman":"Binaa praan pyaare ke himaachal mai galiho |","meaning_en":"without the beloved of my life I would waste away in the Himalaya.","page":1315,"meaning_status":"draft","note":"Could also be read 'with my beloved I will melt in the Himalayan snows'; translated as printed (ਬਿਨਾ, 'without')."},{"gurmukhi":"ਜੌਨ ਹੌ ਸੁ ਹੈਹੌ ਮੁਖ ਦੇਖੋ ਪਾਛੇ ਚਲੀ ਜੈਹੌ","roman":"Jaun hau su haihau mukh dekho paachhe chalee jaihau","meaning_en":"Let what is to be, be; I will see your face and walk behind you,","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਨਾ ਤੌ ਬਿਰਹਾਗਨਿ ਕੀ ਆਗਿ ਬੀਚ ਬਲਿ ਹੋ।","roman":"Naa tau birhaagni kee aagi beech bali ho |","meaning_en":"or else I will burn in the fire of separation.","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਕੌਨ ਕਾਜ ਰਾਜਹੂੰ ਕੋ ਸਾਜ ਮਹਾਰਾਜ ਬਿਨ","roman":"Kaun kaaj raajhoon ko saaj mahaaraaj bin","meaning_en":"Of what use is the array of kingship without the king?","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਨਾਥ ਜੂ ਤਿਹਾਰੋ ਰਹੇ ਰਹੋ ਚਲੇ ਚਲਿਹੋ। ੬੯।","roman":"Naath joo tihaaro rahe raho chale chaliho | 69 |","meaning_en":"My lord, if you stay I stay; if you go I go.","page":1315,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1315,"meaning_status":"draft"},{"type":"verse","number":[70],"number_text":"੭੦।","page":1315,"lines":[{"gurmukhi":"ਦੇਸ ਤਜੋ ਕਰਿ ਭੇਸ ਤਪੋ ਧਨ ਕੇਸ ਮਰੋਰਿ ਜਟਾਨਿ ਸਵਾਰੋ।","roman":"Des tajo kari bhes tapo dhan kes marori jataani savaaro |","meaning_en":"I will leave the country, take the ascetic's garb, twist my hair and dress it in matted locks;","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਲੇਸ ਕਰੌ ਨ ਕਛੂ ਧਨ ਕੌ ਪ੍ਰਭ ਕੀ ਪਨਿਯਾ ਪਰ ਹ੍ਵੈ ਤਨ ਵਾਰੋ।","roman":"Les karau na kachhoo dhan kau prabh kee paniyaa par hvai tan vaaro |","meaning_en":"I will care nothing for wealth; I will offer my body over my lord's shoes;","page":1315,"meaning_status":"draft","note":"ਪਨਿਯਾ: shoes (panahi)."},{"gurmukhi":"ਬਾਲਕ ਕ੍ਰੋਰਿ ਕਰੌ ਇਕ ਓਰ ਸੁ ਬਸਤ੍ਰਨ ਛੋਰਿ ਕੈ ਰਾਮ ਸੰਭਾਰੋ।","roman":"Baalak krori karau ik or su bastran chhori kai raam sanbhaaro |","meaning_en":"I will set ten million children aside, cast off my clothes and remember Ram;","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਇੰਦ੍ਰ ਕੋ ਰਾਜ ਨਹੀ ਮੁਹਿ ਕਾਜ ਬਿਨਾ ਮਹਾਰਾਜ ਸਭੈ ਘਰ ਜਾਰੌ। ੭੦।","roman":"Indr ko raaj nahee muhi kaaj binaa mahaaraaj sabhai ghar jaarau | 70 |","meaning_en":"Indra's kingdom is of no use to me; without my king I would burn the whole house.","page":1315,"meaning_status":"draft"}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":1315,"lines":[{"gurmukhi":"ਅੰਗਨ ਮੈ ਸਜਿ ਹੌ ਭਗਵੈ ਪਟ ਹਾਥ ਬਿਖੈ ਚਿਪਿਯਾ ਗਹਿ ਲੈਹੋ।","roman":"Angan mai saji hau bhagvai pat haath bikhai chipiyaa gahi laiho |","meaning_en":"I will dress my limbs in ochre cloth and take the begging-bowl in my hand;","page":1315,"meaning_status":"draft","note":"ਚਿਪਿਯਾ: the ascetic's bowl."},{"gurmukhi":"ਮੁੰਦ੍ਰਨ ਕਾਨ ਧਰੈ ਅਪਨੇ ਤਵ ਮੂਰਤਿ ਭਿਛਹਿ ਮਾਗਿ ਅਘੈਹੋ।","roman":"Mundran kaan dharai apne tav moorti bhichhhi maagi aghaiho |","meaning_en":"I will put rings in my ears, and be content begging for the alms of your sight;","page":1315,"meaning_status":"draft","note":"ਤਵ ਮੂਰਤਿ ਭਿਛਹਿ: lit. 'the alms of your form'."},{"gurmukhi":"ਨਾਥ ਚਲੌ ਤੁਮ ਠੌਰ ਜਹਾ ਹਮਹੂੰ ਤਿਹ ਠੌਰ ਬਿਖੈ ਚਲਿ ਜੈਹੋ।","roman":"Naath chalau tum thaur jahaa hamhoon tih thaur bikhai chali jaiho |","meaning_en":"lord, wherever you go, I too will go to that place;","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਧਾਮ ਰਹੋ ਨਹਿ ਬਾਤ ਕਹੋ ਪਟ ਫਾਰਿ ਸਭੈ ਅਬ ਜੋਗਿਨ ਹ੍ਵੈਹੋ। ੭੧।","roman":"Dhaam raho nahi baat kaho pat phaari sabhai ab jogin hvaiho | 71 |","meaning_en":"I will not stay at home, I tell you; tearing all my clothes I will now become a yogini.\"","page":1315,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰਾਜਾ ਬਾਚੁ","gurmukhi":"ਰਾਜਾ ਬਾਚੁ","roman":"Raajaa baachu","meaning_en":"The king said:","page":1315,"meaning_status":"draft"},{"type":"verse","number":[72],"number_text":"੭੨।","page":1315,"lines":[{"gurmukhi":"ਰਾਨੀ ਕੋ ਰੂਪ ਨਿਹਾਰਿ ਮਹੀਪਤਿ ਸੋਚ ਬਿਚਾਰ ਕਰਿਯੋ ਚਿਤ ਮਾਹੀ।","roman":"Raanee ko roop nihaari maheepti soch bichaar kariyo chit maahee |","meaning_en":"Seeing the queen's state, the king reflected in his mind:","page":1315,"meaning_status":"draft","note":"ਰੂਪ: lit. 'form'."},{"gurmukhi":"ਰਾਜ ਕਰੋ ਸੁਖ ਸੋ ਸੁਨਿ ਸੁੰਦਰਿ ਤੋਹਿ ਤਜੇ ਲਰਕਾ ਮਰਿ ਜਾਹੀ।","roman":"Raaj karo sukh so suni sundri tohi taje larkaa mari jaahee |","meaning_en":"\"Rule in comfort; listen, fair one, if you leave them the boys will die.\"","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਨ ਮਿਟੈ ਨ ਹਟੈ ਬਨ ਤੇ ਨ੍ਰਿਪ ਝਾਰਿ ਪਛੋਰਿ ਭਲੇ ਅਵਗਾਹੀ।","roman":"So na mitai na hatai ban te nrip jhaari pachhori bhale avgaahee |","meaning_en":"She would not give way nor turn back from the forest; the king sifted and tested her well.","page":1315,"meaning_status":"draft","note":"ਝਾਰਿ ਪਛੋਰਿ: lit. 'shaking and winnowing', i.e. testing thoroughly."},{"gurmukhi":"ਮਾਤ ਪਰੀ ਬਿਲਲਾਤ ਧਰਾ ਪਰ ਨਾਰਿ ਹਠੀ ਹਠ ਛਾਡਤ ਨਾਹੀ। ੭੨।","roman":"Maat paree billaat dharaa par naari hathee hath chhaadat naahee | 72 |","meaning_en":"The mother lay wailing on the ground, but the stubborn woman would not give up her insistence.","page":1315,"meaning_status":"draft","note":"ਮਾਤ: 'mother', taken as the king's mother (see below); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Aril.","page":1315,"meaning_status":"draft"},{"type":"verse","number":[73],"number_text":"੭੩।","page":1315,"lines":[{"gurmukhi":"ਜਬ ਰਾਨੀ ਨ੍ਰਿਪ ਲਖੀ ਸਤਿ ਜੋਗਿਨਿ ਭਈ।","roman":"Jab raanee nrip lakhee sati jogini bhaee |","meaning_en":"When the king saw that the queen had truly become a yogini,","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਛੋਰਿ ਨ ਚਲਿਯੋ ਧਾਮ ਸੰਗ ਅਪੁਨੇ ਲਈ।","roman":"Chhori na chaliyo dhaam sang apune laee |","meaning_en":"he did not leave her at home but took her along with him.","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਧਾਰਿ ਜੋਗ ਕੋ ਭੇਸ ਮਾਤ ਪਹਿ ਆਇਯੋ।","roman":"Dhaari jog ko bhes maat pahi aaiyo |","meaning_en":"Putting on the garb of yoga he came to his mother;","page":1315,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਭੇਸ ਜੋਗ ਨ੍ਰਿਪ ਹੇਰਿ ਸਭਨ ਦੁਖ ਪਾਇਯੋ। ੭੩।","roman":"Ho bhes jog nrip heri sabhan dukh paaiyo | 73 |","meaning_en":"seeing the king in a yogi's garb, everyone was grieved.","page":1315,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1317,"meaning_status":"draft"},{"type":"verse","number":[74],"number_text":"੭੪।","page":1317,"lines":[{"gurmukhi":"ਬਿਦਾ ਦੀਜਿਯੈ ਦਾਸ ਕੌ ਬਨ ਕੌ ਕਰੈ ਪਯਾਨ।","roman":"Bidaa deejiyai daas kau ban kau karai payaan |","meaning_en":"\"Give your servant leave, that he may set out for the forest;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਬੇਦ ਬਿਧਾਨਨ ਧ੍ਯਾਇ ਹੌ ਜੌ ਭਵ ਕੇ ਭਗਵਾਨ। ੭੪।","roman":"Bed bidhaanan dhyaai hau jau bhav ke bhagvaan | 74 |","meaning_en":"by the rites of the Vedas I will meditate on Him who is the Lord of the world.\"","page":1317,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਮਾਤਾ ਬਾਚ","gurmukhi":"ਮਾਤਾ ਬਾਚ","roman":"Maataa baach","meaning_en":"The mother said:","page":1317,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1317,"meaning_status":"draft"},{"type":"verse","number":[75],"number_text":"੭੫।","page":1317,"lines":[{"gurmukhi":"ਪੂਤ ਰਹੌ ਬਲਿ ਜਾਉ ਕਛੂ ਦਿਨ ਪਾਲ ਕਰੌ ਇਨ ਦੇਸਨ ਕੌ।","roman":"Poot rahau bali jaau kachhoo din paal karau in desan kau |","meaning_en":"\"Son, stay some days, I am a sacrifice to you, and protect these lands;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਤੁਹਿ ਕ੍ਯੋ ਕਰਿ ਜਾਨ ਕਹੋ ਮੁਖ ਤੇ ਅਤਿ ਹੀ ਦੁਖ ਲਾਗਤ ਹੈ ਮਨ ਕੌ।","roman":"Tuhi kyo kari jaan kaho mukh te ati hee dukh laagat hai man kau |","meaning_en":"how can I say with my mouth that you may go? It gives my mind great pain.","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਰਿਹ ਤੇ ਤੁਹਿ ਕਾਢਿ ਇਤੋ ਸੁਖ ਛਾਡਿ ਕਹਾ ਕਹਿ ਹੋ ਇਨ ਲੋਗਨ ਕੌ।","roman":"Grih te tuhi kaadhi ito sukh chhaadi kahaa kahi ho in logan kau |","meaning_en":"Having sent you out of the house, giving up such happiness, what shall I say to these people?","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨੁ ਸਾਚੁ ਸਪੂਤ ਕਹੋ ਮੁਖ ਤੇ ਤੁਹਿ ਕੈਸੇ ਕੈ ਦੇਉ ਬਿਦਾ ਬਨ ਕੌ। ੭੫।","roman":"Sunu saachu sapoot kaho mukh te tuhi kaise kai deu bidaa ban kau | 75 |","meaning_en":"Listen, good son, I speak the truth: how can I give you leave for the forest?","page":1317,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1317,"meaning_status":"draft"},{"type":"verse","number":[76],"number_text":"੭੬।","page":1317,"lines":[{"gurmukhi":"ਰਾਜ ਕਰੋ ਸੁਤ ਬਨ ਨ ਪਧਾਰੋ। ਮੇਰੇ ਕਹਿਯੋ ਮੰਤ੍ਰ ਬੀਚਾਰੋ।","roman":"Raaj karo sut ban na padhaaro | mere kahiyo mantr beechaaro |","meaning_en":"Rule, my son, do not go to the forest; consider the counsel I have given;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਲੋਗਨ ਕੇ ਕਹਿਬੋ ਅਨੁਸਰਿਯੈ। ਰਾਜ ਜੋਗ ਘਰਿ ਹੀ ਮਹਿ ਕਰਿਯੈ। ੭੬।","roman":"Logan ke kahibo anusriyai | raaj jog ghari hee mahi kariyai | 76 |","meaning_en":"follow what the people say; practise both kingship and yoga in your own home.\"","page":1317,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਬਾਚ","gurmukhi":"ਰਾਜਾ ਬਾਚ","roman":"Raajaa baach","meaning_en":"The king said:","page":1317,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1317,"meaning_status":"draft"},{"type":"verse","number":[77],"number_text":"੭੭।","page":1317,"lines":[{"gurmukhi":"ਮਾਤਹਿ ਸੀਸ ਝੁਕਾਇ ਕੈ ਪੁਨਿ ਬੋਲਿਯੋ ਨ੍ਰਿਪ ਬੈਨ।","roman":"Maathi sees jhukaai kai puni boliyo nrip bain |","meaning_en":"Bowing his head to his mother, the king spoke again:","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਊਚ ਨੀਚ ਰਾਜਾ ਪ੍ਰਜਾ ਜੈਹੈ ਜਮ ਕੇ ਐਨ। ੭੭।","roman":"Ooch neech raajaa prajaa jaihai jam ke ain | 77 |","meaning_en":"\"High and low, king and subject, all shall go to the house of Yama.\"","page":1317,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1317,"meaning_status":"draft"},{"type":"verse","number":[78],"number_text":"੭੮।","page":1317,"lines":[{"gurmukhi":"ਮਾਤ ਕੀ ਬਾਤ ਨ ਮਾਨੀ ਕਛੂ ਤਜਿ ਰੋਵਤ ਹੀ ਰਨਿਵਾਸਹਿ ਆਯੋ।","roman":"Maat kee baat na maanee kachhoo taji rovat hee ranivaashi aayo |","meaning_en":"He heeded nothing his mother said; leaving her weeping he came to the queens' apartments.","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਆਵਤ ਹੀ ਦਿਜ ਲੋਗ ਬੁਲਾਇ ਜਿਤੋ ਧਨ ਹੋ ਘਰ ਮੋ ਸੁ ਲੁਟਾਯੋ।","roman":"Aavat hee dij log bulaai jito dhan ho ghar mo su lutaayo |","meaning_en":"As soon as he came he called the Brahmins, and gave away all the wealth there was in the house.","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗ ਲਏ ਬਨਿਤਾ ਅਪੁਨੀ ਬਨਿ ਕੈ ਜੁਗਿਯਾ ਬਨ ਓਰ ਸਿਧਾਯੋ।","roman":"Sang lae banitaa apunee bani kai jugiyaa ban or sidhaayo |","meaning_en":"Taking his wife with him, he became a yogi and set out towards the forest.","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗ ਕੈ ਦੇਸ ਭਯੇ ਅਥਿਤੇਸ ਭਜੌ ਜਗਤੇਸ ਯਹੇ ਠਹਰਾਯੋ। ੭੮।","roman":"Tyaag kai des bhaye athites bhajau jagtes yahe thahraayo | 78 |","meaning_en":"Giving up his country he became a mendicant: \"I will worship the Lord of the world\"; this he resolved.","page":1317,"meaning_status":"draft","note":"ਅਥਿਤੇਸ: 'chief of mendicants'."}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":1317,"meaning_status":"draft"},{"type":"verse","number":[79],"number_text":"੭੯।","page":1317,"lines":[{"gurmukhi":"ਲਾਂਬੀ ਲਾਂਬੀ ਸਾਲ ਜਹਾ ਊਚੇ ਬਟ ਤਾਲ ਤਹਾ","roman":"Laanbee laanbee saal jahaa ooche bat taal tahaa","meaning_en":"Where there are tall, tall sal trees, and lofty banyans and palms,","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਐਸੀ ਠੌਰ ਤਪ ਕੋ ਪਧਾਰੈ ਐਸੋ ਕੌਨ ਹੈ।","roman":"Aisee thaur tap ko padhaarai aiso kaun hai |","meaning_en":"who is there that would go to such a place for austerities?","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੀ ਪ੍ਰਭਾ ਦੇਖਿ ਪ੍ਰਭਾ ਖਾਂਡਵ ਕੀ ਫੀਕੀ ਲਾਗੈ","roman":"Jaa kee prabhaa dekhi prabhaa khaandav kee pheekee laagai","meaning_en":"Seeing its splendour, the splendour of the Khandav forest seems pale;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਨੰਦਨ ਨਿਹਾਰਿ ਬਨ ਐਸੋ ਭਜੈ ਮੌਨ ਹੈ।","roman":"Nandan nihaari ban aiso bhajai maun hai |","meaning_en":"seeing such a forest, the Nandan garden falls silent.","page":1317,"meaning_status":"draft","note":"ਨੰਦਨ: Indra's garden. ਭਜੈ ਮੌਨ: 'takes to silence'."},{"gurmukhi":"ਤਾਰਨ ਕੀ ਕਹਾ ਨੈਕੁ ਨਭ ਨ ਨਿਹਾਰਿਯੋ ਜਾਇ","roman":"Taaran kee kahaa naiku nabh na nihaariyo jaai","meaning_en":"What of the stars: not even a little of the sky can be seen;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਸੂਰਜ ਕੀ ਜੋਤਿ ਤਹਾ ਚੰਦ੍ਰ ਕੀ ਨ ਜੌਨ ਹੈ।","roman":"Sooraj kee joti tahaa chandr kee na jaun hai |","meaning_en":"there is no light of the sun there, nor moonlight;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵ ਨ ਨਿਹਾਰਿਯੋ ਦੈਤ ਕੋਊ ਨ ਬਿਹਾਰਿਯੋ ਜਹਾ","roman":"Dev na nihaariyo dait ko'oo na bihaariyo jahaa","meaning_en":"no god has seen it, no demon has roamed there;","page":1317,"meaning_status":"draft"},{"gurmukhi":"ਪੰਛੀ ਕੀ ਨ ਗੰਮ੍ਯ ਤਹਾ ਚੀਟੀ ਕੋ ਨ ਗੌਨ ਹੈ। ੭੯।","roman":"Panchhee kee na ganmy tahaa cheetee ko na gaun hai | 79 |","meaning_en":"no bird has access there, no ant can make its way.","page":1317,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1319,"meaning_status":"draft"},{"type":"verse","number":[80],"number_text":"੮੦।","page":1319,"lines":[{"gurmukhi":"ਜਬ ਐਸੇ ਬਨ ਮੈ ਦੋਊ ਗਏ। ਹੇਰਤ ਤਵਨ ਮਹਲ ਕੋ ਭਏ।","roman":"Jab aise ban mai do'oo gae | herat tavan mahal ko bhae |","meaning_en":"When the two went into such a forest, they caught sight of that mansion.","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰਤੁ ਤਾਹਿ ਨ੍ਰਿਪ ਬਚਨ ਸੁਨਾਯੋ। ਤਪ ਕੋ ਭਲੇ ਠੌਰ ਹਮ ਪਾਯੋ। ੮੦।","roman":"Turtu taahi nrip bachan sunaayo | tap ko bhale thaur ham paayo | 80 |","meaning_en":"At once the king said to her, \"We have found a good place for austerities.\"","page":1319,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਰਾਨੀ ਬਾਚ","gurmukhi":"ਰਾਨੀ ਬਾਚ","roman":"Raanee baach","meaning_en":"The queen said:","page":1319,"meaning_status":"draft"},{"type":"verse","number":[81],"number_text":"੮੧।","page":1319,"lines":[{"gurmukhi":"ਯਾ ਮੈ ਬੈਠਿ ਤਪਸ੍ਯਾ ਕਰਿ ਹੈ। ਰਾਮ ਰਾਮ ਮੁਖ ਤੇ ਉਚਰਿ ਹੈ।","roman":"Yaa mai baithi tapsyaa kari hai | raam raam mukh te uchri hai |","meaning_en":"\"Sitting in this we will practise austerities, and utter 'Ram, Ram' with our mouths;","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਘਰ ਮੈ ਦਿਨ ਕਿਤਕ ਬਿਤੈ ਹੈ। ਭਸਮੀ ਭੂਤ ਪਾਪ ਸਭ ਕੈ ਹੈ। ੮੧।","roman":"Yaa ghar mai din kitak bitai hai | bhasmee bhoot paap sabh kai hai | 81 |","meaning_en":"we will spend some days in this house and burn all our sins to ashes.\"","page":1319,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1319,"meaning_status":"draft"},{"type":"verse","number":[82],"number_text":"੮੨।","page":1319,"lines":[{"gurmukhi":"ਰਾਨੀ ਜਾਹਿ ਬੁਲਾਇ ਕੈ ਭੇਦ ਕਹਿਯੋ ਸਮਝਾਇ।","roman":"Raanee jaahi bulaai kai bhed kahiyo samjhaai |","meaning_en":"The man whom the queen had called and told the secret,","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਵਹੈ ਪੁਰਖ ਜੁਗਿਯਾ ਬਨ੍ਯੋ ਨ੍ਰਿਪਹਿ ਮਿਲਤ ਭਯੋ ਆਇ। ੮੨।","roman":"Vahai purakh jugiyaa banyo nriphi milat bhayo aai | 82 |","meaning_en":"that same man, dressed as a yogi, came and met the king.","page":1319,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1319,"meaning_status":"draft"},{"type":"verse","number":[83],"number_text":"੮੩।","page":1319,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਕੋ ਤ੍ਰਿਯਹਿ ਕਹਿਯੋ ਸਮੁਝਾਈ। ਜੋਗੀ ਵਹੈ ਪਹੂੰਚ੍ਯੋ ਆਈ।","roman":"Nrip ko triyhi kahiyo samujhaaee | jogee vahai pahoonchyo aaee |","meaning_en":"The woman explained to the king: \"That very yogi has arrived;","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਮਰਤ ਬਚਨ ਮੋ ਸੋ ਤਿਨ ਕਹਿਯੋ। ਸੋ ਮੈ ਆਜੁ ਸਾਚੁ ਕਰਿ ਲਹਿਯੋ। ੮੩।","roman":"Marat bachan mo so tin kahiyo | so mai aaju saachu kari lahiyo | 83 |","meaning_en":"the words he spoke to me as he was dying, today I have found them true.\"","page":1319,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1319,"meaning_status":"draft"},{"type":"verse","number":[84],"number_text":"੮੪।","page":1319,"lines":[{"gurmukhi":"ਉਠਿ ਰਾਜਾ ਪਾਇਨ ਪਰਿਯੋ ਤਾ ਕਹ ਗੁਰੂ ਪਛਾਨਿ।","roman":"Uthi raajaa paain pariyo taa kah guroo pachhaani |","meaning_en":"The king rose and fell at his feet, recognising him as his Guru;","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਬੈਠਿ ਗੋਸਟਿ ਦੋਨੋ ਕਰੀ ਸੋ ਮੈ ਕਹਤ ਬਖਾਨਿ। ੮੪।","roman":"Baithi gosti dono karee so mai kahat bakhaani | 84 |","meaning_en":"the two sat and conversed; I relate what they said.","page":1319,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਜੋਗੀ ਬਾਚ","gurmukhi":"ਜੋਗੀ ਬਾਚ","roman":"Jogee baach","meaning_en":"The yogi said:","page":1319,"meaning_status":"draft"},{"type":"verse","number":[85],"number_text":"੮੫।","page":1319,"lines":[{"gurmukhi":"ਨ੍ਹਾਇ ਨਦੀ ਸੋ ਜੋ ਨ੍ਰਿਪਤਿ ਬੈਠਹੁਗੇ ਹ੍ਯਾ ਆਇ।","roman":"Nhaai nadee so jo nripti baithhuge hyaa aai |","meaning_en":"\"When you have bathed in the river, O king, and come and sit here,","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਤੁਮ ਸੈ ਮੈ ਭਾਖਿਹੋ ਬ੍ਰਹਮ ਬਾਦਿ ਸਮੁਝਾਇ। ੮੫।","roman":"Tab tum sai mai bhaakhiho braham baadi samujhaai | 85 |","meaning_en":"then I will explain to you the discourse on Brahm.\"","page":1319,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1319,"meaning_status":"draft"},{"type":"verse","number":[86],"number_text":"੮੬।","page":1319,"lines":[{"gurmukhi":"ਐਸੇ ਜਤਨ ਨ੍ਰਿਪਤਿ ਕੋ ਟਾਰਿਯੋ। ਛਾਤ ਬਿਖੈ ਇਕ ਨਰ ਪੈਠਾਰਿਯੋ।","roman":"Aise jatan nripti ko taariyo | chhaat bikhai ik nar paithaariyo |","meaning_en":"By this device the king was sent away, and a man was put into the roof:","page":1319,"meaning_status":"draft","note":"Subject not stated (the queen or the false yogi)."},{"gurmukhi":"ਸਾਧੁ ਸਾਧੁ ਇਹ ਬਚ ਸੁਨਿ ਕਹਿਯਹੁ। ਤੀਨ ਬਾਰ ਕਹਿ ਕੈ ਚੁਪ ਰਹਿਯਹੁ। ੮੬।","roman":"Saadhu saadhu ih bach suni kahiyhu | teen baar kahi kai chup rahiyhu | 86 |","meaning_en":"\"On hearing these words say 'Well said, well said'; say it three times and then keep silent.\"","page":1319,"meaning_status":"draft","note":"ਸਾਧੁ ਸਾਧੁ: 'well said'; at verse 94 the words actually spoken are printed ਸਤਿ ਸਤਿ ('true, true')."}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":1319,"lines":[{"gurmukhi":"ਨ੍ਹਾਇ ਧੋਇ ਰਾਜਾ ਜਬ ਆਯੋ। ਤਬ ਤਿਹ ਨਰ ਯੌ ਬਚਨ ਸੁਨਾਯੋ।","roman":"Nhaai dhoi raajaa jab aayo | tab tih nar yau bachan sunaayo |","meaning_en":"When the king came back bathed and washed, that man spoke these words:","page":1319,"meaning_status":"draft","note":"'That man': taken as the false yogi (Anup Singh), not the man hidden in the roof."},{"gurmukhi":"ਸੁਨੁ ਨ੍ਰਿਪ ਜਬ ਮਾਟੀ ਮੈ ਲਈ। ਧਰਮ ਰਾਜ ਆਗ੍ਯਾ ਮੁਹਿ ਦਈ। ੮੭।","roman":"Sunu nrip jab maatee mai laee | dharam raaj aagyaa muhi daee | 87 |","meaning_en":"\"Listen, O king: when I took to the earth, Dharamraj gave me a command:","page":1319,"meaning_status":"draft","note":"ਮਾਟੀ ਮੈ ਲਈ: lit. 'I took the earth', i.e. died and was laid in the earth (cf. verse 30)."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1319,"meaning_status":"draft"},{"type":"verse","number":[88],"number_text":"੮੮।","page":1319,"lines":[{"gurmukhi":"ਤੈ ਰਾਜਾ ਕੋ ਤੀਰ ਤਜਿ ਕ੍ਯੋ ਆਯੋ ਇਹ ਠੌਰ।","roman":"Tai raajaa ko teer taji kyo aayo ih thaur |","meaning_en":"'Why have you left the king's side and come to this place?","page":1319,"meaning_status":"draft"},{"gurmukhi":"ਮੋ ਸੌ ਬ੍ਰਿਥਾ ਬਖਾਨਿਯੈ ਸੁਨੁ ਜੋਗਿਨ ਸਿਰਮੌਰ। ੮੮।","roman":"Mo sau brithaa bakhaaniyai sunu jogin sirmaur | 88 |","meaning_en":"Tell me your account; listen, O crown of yogis.'","page":1319,"meaning_status":"draft","note":"ਬ੍ਰਿਥਾ: read as 'account, tale of trouble' (birtha)."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1321,"meaning_status":"draft"},{"type":"verse","number":[89],"number_text":"੮੯।","page":1321,"lines":[{"gurmukhi":"ਧਰਮ ਰਾਜ ਮੁਹਿ ਬਚਨ ਉਚਾਰੇ। ਸੁ ਹੌ ਕਹਤ ਹੌ ਤੀਰ ਤਿਹਾਰੇ।","roman":"Dharam raaj muhi bachan uchaare | su hau kahat hau teer tihaare |","meaning_en":"Dharamraj spoke words to me, and I tell them before you:","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਮੋਰੀ ਕਹੀ ਰਾਵ ਸੌ ਕਹਿਯਹੁ। ਨਾਤਰ ਭ੍ਰਮਤ ਨਰਕ ਮਹਿ ਰਹਿਯਹੁ। ੮੯।","roman":"Moree kahee raav sau kahiyhu | naatar bhramat narak mahi rahiyhu | 89 |","meaning_en":"'Tell the king what I say, or else you will remain wandering in hell.","page":1321,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":1321,"lines":[{"gurmukhi":"ਜੈਸੋ ਕੋਟਿ ਜਗ੍ਯ ਤਪੁ ਕੀਨੋ। ਤੈਸੋ ਸਾਚ ਨ੍ਯਾਇ ਕਰਿ ਦੀਨੋ।","roman":"Jaiso koti jagy tapu keeno | taiso saach nyaai kari deeno |","meaning_en":"As is the performing of millions of sacrifices and austerities, so is the giving of true justice;","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਯਾਇ ਸਾਸਤ੍ਰ ਲੈ ਰਾਜ ਕਮਾਵੈ। ਤਾ ਕੇ ਨਿਕਟ ਕਾਲ ਨਹੀ ਆਵੈ। ੯੦।","roman":"Nyaai saasatr lai raaj kamaavai | taa ke nikat kaal nahee aavai | 90 |","meaning_en":"he who rules by the shastra of justice, Death does not come near him.","page":1321,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1321,"meaning_status":"draft"},{"type":"verse","number":[91],"number_text":"੯੧।","page":1321,"lines":[{"gurmukhi":"ਜੋ ਨ੍ਰਿਪ ਨ੍ਯਾਇ ਕਰੈ ਨਹੀ ਬੋਲਤ ਝੂਠ ਬਨਾਇ।","roman":"Jo nrip nyaai karai nahee bolat jhooth banaai |","meaning_en":"The king who does no justice, and speaks contrived lies,","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਤ੍ਯਾਗ ਤਪਸ੍ਯਾ ਕਰੈ ਪਰੈ ਨਰਕ ਮਹਿ ਜਾਇ। ੯੧।","roman":"Raaj tyaag tapsyaa karai parai narak mahi jaai | 91 |","meaning_en":"who gives up his kingdom and practises austerities, goes and falls into hell.","page":1321,"meaning_status":"draft"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":1321,"lines":[{"gurmukhi":"ਬ੍ਰਿਧ ਮਾਤਾ ਅਰੁ ਤਾਤ ਕੀ ਸੇਵਾ ਕਰਿਯੋ ਨਿਤ।","roman":"Bridh maataa aru taat kee sevaa kariyo nit |","meaning_en":"Serve your aged mother and father always;","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗ ਨ ਬਨ ਕੋ ਜਾਇਯੈ ਯਹੈ ਧਰਮੁ ਸੁਨੁ ਮਿਤ। ੯੨।","roman":"Tyaag na ban ko jaaiyai yahai dharmu sunu mit | 92 |","meaning_en":"do not forsake them and go to the forest; this is dharma, listen, friend.'","page":1321,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":1321,"lines":[{"gurmukhi":"ਜੌ ਹੌ ਜੋਗੀ ਵਹੈ ਹੌ ਪਠੈ ਦਯੋ ਧ੍ਰਮਰਾਇ।","roman":"Jau hau jogee vahai hau pathai dayo dhramraai |","meaning_en":"If I am that same yogi, sent by Dharamrai,","page":1321,"meaning_status":"draft","note":"ਜੌ: read as 'if'. The construction of this couplet is uncertain."},{"gurmukhi":"ਹੌ ਈਹਾ ਬੋਲੈ ਤੁਰਤੁ ਅਪਨੋ ਰੂਪ ਛਪਾਇ। ੯੩।","roman":"Hau eehaa bolai turtu apno roop chhapaai | 93 |","meaning_en":"then one will speak here at once, keeping his own form hidden.\"","page":1321,"meaning_status":"draft","note":"ਹੌ ... ਬੋਲੈ: read as 'someone will speak'; uncertain."}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":1321,"lines":[{"gurmukhi":"ਜਬ ਜੋਗੀ ਐਸੇ ਕਹਿਯੋ ਤਾਹਿ ਭੇਦ ਸਮੁਝਾਇ।","roman":"Jab jogee aise kahiyo taahi bhed samujhaai |","meaning_en":"When the yogi had spoken thus, explaining the secret to him,","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਸਤਿ ਤਬ ਤਿਨ ਕਹਿਯੋ ਤੀਨ ਬਾਰ ਮੁਸਕਾਇ। ੯੪।","roman":"Sati sati tab tin kahiyo teen baar muskaai | 94 |","meaning_en":"then that one said \"True, true\" three times, smiling.","page":1321,"meaning_status":"draft","note":"'That one': the man hidden in the roof."}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":1321,"lines":[{"gurmukhi":"ਜਿਯਬੋ ਜਗ ਕੌ ਸਹਲ ਹੈ ਯਹੈ ਕਠਿਨ ਦ੍ਵੈ ਕਾਮ।","roman":"Jiybo jag kau sahal hai yahai kathin dvai kaam |","meaning_en":"\"To live in the world is easy; these two tasks are hard:","page":1321,"meaning_status":"draft","note":"Taken as the words of the hidden voice; speaker not marked."},{"gurmukhi":"ਪ੍ਰਾਤ ਸੰਭਰਿਬੋ ਰਾਜ ਕੋ ਰਾਤਿ ਸੰਭਰਿਬੋ ਰਾਮ। ੯੫।","roman":"Praat sanbhribo raaj ko raati sanbhribo raam | 95 |","meaning_en":"in the morning to mind the kingdom, and at night to remember Ram.\"","page":1321,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1321,"meaning_status":"draft"},{"type":"verse","number":[96],"number_text":"੯੬।","page":1321,"lines":[{"gurmukhi":"ਮਹਾਰਾਜ ਜੈਸੀ ਸੁਨਿ ਬਾਨੀ। ਚਿਤ ਕੈ ਬਿਖੈ ਸਾਚ ਕਰਿ ਮਾਨੀ।","roman":"Mahaaraaj jaisee suni baanee | chit kai bikhai saach kari maanee |","meaning_en":"When the great king heard such a voice, he accepted it as true in his heart:","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਦਿਨ ਕੌ ਰਾਜੁ ਆਪਨੌ ਕਰਿਹੌ। ਪਰੇ ਰਾਤ੍ਰਿ ਕੇ ਰਾਮ ਸੰਭਰਿਹੌ। ੯੬।","roman":"Din kau raaju aapnau karihau | pare raatri ke raam sanbhrihau | 96 |","meaning_en":"\"By day I will rule my kingdom; when night falls I will remember Ram.\"","page":1321,"meaning_status":"draft"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":1321,"lines":[{"gurmukhi":"ਰਾਨੀ ਮਹਾਰਾਜ ਸਮਝਾਇਸਿ। ਜੋਗ ਮਾਰਗ ਤੇ ਛਲਿ ਬਹੁਰਾਇਸਿ।","roman":"Raanee mahaaraaj samjhaaisi | jog maarag te chhali bahuraaisi |","meaning_en":"The queen brought the great king round; by a trick she turned him back from the path of yoga.","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਧਰਿ ਬਸਤ੍ਰ ਧਾਮ ਮੈ ਆਯੋ। ਬਹੁਰ ਆਪਨੌ ਰਾਜ ਕਮਾਯੋ। ੯੭।","roman":"Nrip dhari basatr dhaam mai aayo | bahur aapnau raaj kamaayo | 97 |","meaning_en":"The king put on his clothes and came home, and ruled his kingdom again.","page":1321,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1321,"meaning_status":"draft"},{"type":"verse","number":[98,1],"number_text":"੯੮। ੧।","page":1321,"lines":[{"gurmukhi":"ਜਿਯਤੇ ਜੁਗਿਯਾ ਮਾਰਿਯੋ ਭੂਅ ਕੇ ਬਿਖੈ ਗਡਾਇ।","roman":"Jiyte jugiyaa maariyo bhooa ke bikhai gadaai |","meaning_en":"She killed the yogi by burying him alive in the ground;","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਿਯ ਨ੍ਰਿਪ ਕੋ ਬਹੁਰਾਇਯੋ ਐਸੇ ਚਰਿਤ ਬਨਾਇ। ੯੮। ੧।","roman":"Triy nrip ko bahuraaiyo aise charit banaai | 98 | 1 |","meaning_en":"the woman brought the king back by contriving such a charitra.","page":1321,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਇਕਾਸੀਵੋ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade ikaaseevo charitr samaaptam","meaning_en":"Thus ends the eighty-first charitra of the Charitropakhyan, of the wiles of women, in the dialogue of the minister and the king; complete.","page":1321,"meaning_status":"draft"},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੮੧। ੧੪੪੨। ਅਫਜੂੰ।","roman":"Satu subham satu | 81 | 1442 | aphjoon |","meaning_en":"True, auspicious, true. 81. 1442. It continues.","page":1321,"meaning_status":"draft","note":"ਅਫਜੂੰ: Persian 'increasing, more'; a customary closing word."}],"page":1321,"number":[81,1442]}});
